const STATUS_COLORS: Record<string, string> = {
  Pagada: "bg-green-100 text-green-800",
  Pendiente: "bg-yellow-100 text-yellow-800",
  Cancelada: "bg-red-100 text-red-800",
  "En curso": "bg-blue-100 text-blue-800",
  Completada: "bg-gray-100 text-gray-800",
  "No asisti├│": "bg-orange-100 text-orange-800",
};

interface AppointmentStatusBadgeProps {
  /** The appointment status name to display */
  readonly statusName: string;
}

/**
 * Renders a colored badge for an appointment status.
 * Defaults to gray styling when the status is not in the color map.
 */
export function AppointmentStatusBadge({ statusName }: AppointmentStatusBadgeProps) {
  const colorClass = STATUS_COLORS[statusName] ?? "bg-gray-100 text-gray-800";

  return (
    <span className={`px-2 py-1 rounded-full text-xs font-semibold ${colorClass}`}>
      {statusName || "ÔÇö"}
    </span>
  );
}

interface MedicineControlledBadgeProps {
  /** Whether the medicine is a controlled substance */
  readonly isControlled: boolean;
}

/**
 * Renders a warning badge when a medicine is classified as controlled.
 * Returns null when isControlled is false.
 */
export function MedicineControlledBadge({ isControlled }: MedicineControlledBadgeProps) {
  if (!isControlled) {
    return null;
  }

  return (
    <span className="inline-flex items-center gap-1 rounded-full bg-orange-100 px-2.5 py-0.5 text-xs font-semibold text-orange-800 border border-orange-300">
      <span aria-hidden="true">ÔÜá´©Å</span>
      Controlado
    </span>
  );
}

const NOTIFICATION_STATUS: Record<number, { label: string; color: string }> = {
  0: { label: "Pendiente", color: "bg-yellow-100 text-yellow-800" },
  1: { label: "Enviado", color: "bg-green-100 text-green-800" },
  2: { label: "Fallido", color: "bg-red-100 text-red-800" },
  3: { label: "Reintentando", color: "bg-blue-100 text-blue-800" },
};

interface NotificationStatusBadgeProps {
  /** Numeric status code: 0=Pendiente, 1=Enviado, 2=Fallido, 3=Reintentando */
  readonly status: number;
}

/**
 * Renders a colored badge for a notification status code.
 * Defaults to gray styling when the status code is not recognized.
 */
export function NotificationStatusBadge({ status }: NotificationStatusBadgeProps) {
  const entry = NOTIFICATION_STATUS[status] ?? { label: String(status), color: "bg-gray-100 text-gray-800" };

  return (
    <span className={`px-2 py-1 rounded-full text-xs font-semibold ${entry.color}`}>
      {entry.label}
    </span>
  );
}

