interface LogoHISProps {
  readonly width?: string | number;
  readonly height?: string | number;
  readonly className?: string;
}

export function LogoHIS({ width = "200px", height = "auto", className }: LogoHISProps) {
  return (
    <svg
      className={className}
      height={height}
      width={width}
      viewBox="0 0 320 100" // Espacio justo para que no flote
      xmlns="http://www.w3.org/2000/svg"
      preserveAspectRatio="xMidYMid meet"
    >
      {/* Icono: Usamos currentColor para que herede el color del texto del tema */}
      <g transform="translate(10, 15)">
        <path
          d="M30 0H40V70H30V0Z M0 30H70V40H0V30Z"
          fill="currentColor"
          className="text-blue-600 dark:text-blue-400"
        />
        <circle cx="35" cy="5" fill="#00D4FF" r="6" />
        <circle cx="35" cy="65" fill="#00D4FF" r="6" />
        <circle cx="5" cy="35" fill="#00D4FF" r="6" />
        <circle cx="65" cy="35" fill="#00D4FF" r="6" />
      </g>

      {/* Texto: Hereda la fuente y color del sistema */}
      <text
        fill="currentColor"
        fontFamily="inherit"
        fontSize="48"
        fontWeight="bold"
        x="100"
        y="70"
        className="text-gray-800 dark:text-gray-100"
      >
        HIS
        <tspan dy="-18" fill="#00D4FF" fontSize="24">
          SYSTEM
        </tspan>
      </text>

      {/* L├¡nea inferior */}
      <rect fill="#00D4FF" height="4" rx="2" width="200" x="100" y="82" />
    </svg>
  );
}

export default LogoHIS;

import { Button, Dropdown, toast } from "@heroui/react";
import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useNavigate } from "react-router";
import { deleteAppointment } from "../../services/appointmentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";
import { validationFailureToString } from "../../utils/converted";
import { Icon } from "../icons/Icon";
import { ConfirmDialog } from "../modal/ConfirmDialog";

interface AppointmentButtonProps {
  readonly data: AppointmentResponse;
}

export function AppointmentButton({ data }: AppointmentButtonProps) {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleView = useCallback(() => {
    navigate(`/appointment/view/${data.id}`);
  }, [navigate, data.id]);

  const handleDeleteClick = useCallback(() => setIsDeleteDialogOpen(true), []);

  const handleDeleteConfirm = useCallback(async () => {
    setIsDeleting(true);
    try {
      const response = await deleteAppointment(data.id);
      if (response.success) {
        toast.success(`Cita #${data.id} eliminada correctamente`);
        await queryClient.invalidateQueries({ queryKey: ["appointments"] });
        setIsDeleteDialogOpen(false);
      } else {
        toast.danger(`No se pudo eliminar: ${response.message} ${validationFailureToString(response.data)}`);
      }
    } catch (error) {
      toast.danger(`Error: ${error instanceof Error ? error.message : "Error desconocido"}`);
    } finally {
      setIsDeleting(false);
    }
  }, [data, queryClient]);

  const handleCloseDialog = useCallback(() => {
    if (!isDeleting) setIsDeleteDialogOpen(false);
  }, [isDeleting]);

  return (
    <>
      <Dropdown>
        <Dropdown.Trigger>
          <Button isIconOnly size="sm" variant="primary">
            <Icon name="bi bi-three-dots-vertical" />
          </Button>
        </Dropdown.Trigger>
        <Dropdown.Popover>
          <Dropdown.Menu aria-label="Acciones de cita">
            <Dropdown.Item key="view" className="text-primary hover:text-white" onClick={handleView}>
              Ver Detalle
            </Dropdown.Item>
            <Dropdown.Item key="delete" className="text-danger hover:text-white" onClick={handleDeleteClick}>
              Eliminar
            </Dropdown.Item>
          </Dropdown.Menu>
        </Dropdown.Popover>
      </Dropdown>
      <ConfirmDialog
        cancelText="Cancelar"
        confirmText="Eliminar"
        isLoading={isDeleting}
        isOpen={isDeleteDialogOpen}
        message={`┬┐Est├í seguro que desea eliminar la cita #${data.id}?`}
        title="Confirmar eliminaci├│n"
        onClose={handleCloseDialog}
        onConfirm={handleDeleteConfirm}
      />
    </>
  );
}

