import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useCallback, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import { AsyncButton } from "../button/AsyncButton";
import { useForm } from "../../hooks/useForm";
import type { ApiResponse } from "../../types/ApiResponse";
import type { SpecialtyRequest } from "../../types/SpecialtyResponse";
import type { ValidationFailure } from "../../types/ValidationFailure";
import { validateSpecialty } from "../../validations/specialtyValidation";
import { Response } from "../messages/Response";
import { OptionsSelect, type OptionValue } from "../select/OptionsSelect";

interface SpecialtyFormProps {
  readonly type: "create" | "edit";
  readonly initialForm: SpecialtyRequest;
  readonly onSubmit: (form: SpecialtyRequest) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
}

export function SpecialtyForm({ type, initialForm, onSubmit }: SpecialtyFormProps) {
  const isEditing = type === "edit";
  const navigate = useNavigate();

  const { form, errors, handleChange, handleSubmit, success, message, loading } =
    useForm<SpecialtyRequest, unknown>(initialForm, validateSpecialty, onSubmit, true);

  const handleTextChange = useCallback(
    (name: string) => (val: string) => {
      handleChange({ target: { name, value: val } } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleStateChange = useCallback(
    (newValue: OptionValue) => {
      const value = newValue && !Array.isArray(newValue) && "value" in newValue
        ? Number((newValue as { value: string }).value) : null;
      handleChange({ target: { name: "state", value } } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        {isEditing ? "Editar Especialidad" : "Crear Especialidad"}
      </h1>
      {success != null && <Response message={message} type={success} />}
      <Form className="flex flex-col gap-4" validationErrors={errors} onSubmit={handleSubmit}>
        <TextField isRequired className="w-full flex flex-col gap-1" isInvalid={!!errors?.name} name="name" onChange={handleTextChange("name")}>
          <Label className="font-bold">Nombre</Label>
          <Input className="w-full px-3 py-2 border rounded-md" type="text" value={form.name || ""} />
          {errors?.name ? <FieldError>{errors.name as string}</FieldError> : null}
        </TextField>
        <TextField isRequired className="w-full flex flex-col gap-1" isInvalid={!!errors?.description} name="description" onChange={handleTextChange("description")}>
          <Label className="font-bold">Descripci├│n</Label>
          <Input className="w-full px-3 py-2 border rounded-md" type="text" value={form.description || ""} />
          {errors?.description ? <FieldError>{errors.description as string}</FieldError> : null}
        </TextField>
        <OptionsSelect
          isRequired
          defaultValue={form.state !== null && form.state !== undefined
            ? { label: form.state === 1 ? "Activo" : "Inactivo", value: String(form.state) }
            : { label: "Activo", value: "1" }}
          errorMessage={errors?.state as string}
          isInvalid={!!errors?.state}
          label="Estado"
          name="state"
          options={[{ label: "Activo", value: "1" }, { label: "Inactivo", value: "0" }]}
          placeholder="Seleccione un estado"
          onChange={handleStateChange}
        />
        <div className="flex gap-4 justify-end mt-4">
          <AsyncButton className="font-bold" isLoading={false} size="lg" type="button" variant="secondary" onClick={() => navigate("/specialty")}>
            Cancelar
          </AsyncButton>
          <AsyncButton className="font-bold" isLoading={loading} loadingText={isEditing ? "Actualizando..." : "Creando..."} size="lg" type="submit" variant="primary">
            {isEditing ? "Actualizar" : "Crear"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import {
  FieldError,
  Form,
  Input,
  Label,
  TextField,
} from "@heroui/react";
import { useCallback, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import type { SingleValue } from "react-select";
import { AsyncButton } from "../button/AsyncButton";
import { useForm } from "../../hooks/useForm";
import { getBranches } from "../../services/branchService";
import { getRoles } from "../../services/rolService";
import { getSpecialties } from "../../services/specialtyService";
import type { ApiResponse } from "../../types/ApiResponse";
import type { BranchResponse } from "../../types/BranchResponse";
import type { RolResponse } from "../../types/RolResponse";
import type { SpecialtyResponse } from "../../types/SpecialtyResponse";
import type { UserRequest } from "../../types/UserRequest";
import type { ValidationFailure } from "../../types/ValidationFailure";
import { validateUser } from "../../validations/userValidation";
import { Response } from "../messages/Response";
import { CatalogueSelect } from "../select/CatalogueSelect";
import { OptionsSelect, type OptionValue } from "../select/OptionsSelect";

interface CreateUserFormProps {
  readonly type: "create";
  readonly initialForm: UserRequest;
  readonly onSubmit: (
    form: UserRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
}

interface EditUserFormProps {
  readonly type: "edit";
  readonly initialForm: UserRequest;
  readonly onSubmit: (
    form: UserRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
}

type UserFormProps = CreateUserFormProps | EditUserFormProps;

export function UserForm({ type, initialForm, onSubmit }: UserFormProps) {
  const isEditing = type === "edit";
  const navigate = useNavigate();

  const { form, errors, handleChange, handleSubmit, success, message, loading } =
    useForm<UserRequest, unknown>(initialForm, validateUser, onSubmit, true);

  const handleTextChange = useCallback(
    (name: string) => (val: string) => {
      handleChange({
        target: { name, value: val },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleSelectChange = useCallback(
    (name: string) => (opt: OptionValue) => {
      const option = opt as SingleValue<{ label: string; value: string }>;
      handleChange({
        target: { name, value: option?.value || "" },
      } as React.ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const selectorRol = useCallback(
    (item: RolResponse) => ({
      label: item.description,
      value: String(item.id),
    }),
    [],
  );

  const selectorBranch = useCallback(
    (item: BranchResponse) => ({
      label: item.name,
      value: String(item.id),
    }),
    [],
  );

  const selectorSpecialty = useCallback(
    (item: SpecialtyResponse) => ({
      label: item.name,
      value: String(item.id),
    }),
    [],
  );

  const handleCancel = useCallback(() => {
    navigate("/user");
  }, [navigate]);

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">
        {isEditing ? "Editar Usuario" : "Crear Usuario"}
      </h1>

      {success != null && <Response message={message} type={success} />}

      <Form
        className="flex flex-col gap-4"
        validationErrors={errors}
        onSubmit={handleSubmit}
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.name}
            name="name"
            onChange={handleTextChange("name")}
          >
            <Label className="font-bold">Nombre Completo</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.name || ""}
            />

            {errors?.name ? (
              <FieldError>{errors.name as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.email}
            name="email"
            onChange={handleTextChange("email")}
          >
            <Label className="font-bold">Correo Electr├│nico</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="email"
              value={form.email || ""}
            />

            {errors?.email ? (
              <FieldError>{errors.email as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.userName}
            name="userName"
            onChange={handleTextChange("userName")}
          >
            <Label className="font-bold">Nombre de Usuario</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.userName || ""}
            />

            {errors?.userName ? (
              <FieldError>{errors.userName as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.password}
            isRequired={!isEditing}
            name="password"
            onChange={handleTextChange("password")}
          >
            <Label className="font-bold">
              {isEditing ? "Nueva Contrase├▒a (opcional)" : "Contrase├▒a"}
            </Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="password"
              value={form.password || ""}
            />

            {errors?.password ? (
              <FieldError>{errors.password as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.identificationDocument}
            name="identificationDocument"
            onChange={handleTextChange("identificationDocument")}
          >
            <Label className="font-bold">Documento de Identificaci├│n</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.identificationDocument || ""}
            />

            {errors?.identificationDocument ? (
              <FieldError>{errors.identificationDocument as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.number}
            name="number"
            onChange={handleTextChange("number")}
          >
            <Label className="font-bold">N├║mero de Tel├®fono</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.number || ""}
            />

            {errors?.number ? (
              <FieldError>{errors.number as string}</FieldError>
            ) : null}
          </TextField>

          <CatalogueSelect
            isRequired
            defaultValue={
              type === "edit"
                ? {
                    label: initialForm.rol?.name ?? "",
                    value: initialForm.rolId?.toString() ?? "",
                  }
                : null
            }
            deps="State:eq:1"
            errorMessage={errors?.rolId as string}
            fieldSearch="Name"
            isInvalid={!!errors?.rolId}
            label="Rol"
            name="rolId"
            placeholder="Seleccione un rol"
            queryFn={getRoles}
            selectorFn={selectorRol}
            onChange={handleSelectChange("rolId")}
          />

          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.nit}
            name="nit"
            onChange={handleTextChange("nit")}
          >
            <Label className="font-bold">NIT</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.nit || ""}
            />
            {errors?.nit ? (
              <FieldError>{errors.nit as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.insuranceNumber}
            name="insuranceNumber"
            onChange={handleTextChange("insuranceNumber")}
          >
            <Label className="font-bold">N├║mero de Seguro</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              type="text"
              value={form.insuranceNumber || ""}
            />
            {errors?.insuranceNumber ? (
              <FieldError>{errors.insuranceNumber as string}</FieldError>
            ) : null}
          </TextField>

          <CatalogueSelect
            defaultValue={
              type === "edit" && form.branchId
                ? {
                    label: String(form.branchId),
                    value: String(form.branchId),
                  }
                : null
            }
            deps="State:eq:1"
            errorMessage={errors?.branchId as string}
            fieldSearch="Name"
            isInvalid={!!errors?.branchId}
            label="Sucursal"
            name="branchId"
            placeholder="Seleccione una sucursal (opcional)"
            queryFn={getBranches}
            selectorFn={selectorBranch}
            onChange={handleSelectChange("branchId")}
          />

          <CatalogueSelect
            defaultValue={
              type === "edit" && form.specialtyId
                ? {
                    label: form.specialty?.name ?? String(form.specialtyId),
                    value: String(form.specialtyId),
                  }
                : null
            }
            deps="State:eq:1"
            errorMessage={errors?.specialtyId as string}
            fieldSearch="Name"
            isInvalid={!!errors?.specialtyId}
            label="Especialidad (M├®dicos)"
            name="specialtyId"
            placeholder="Seleccione una especialidad (opcional)"
            queryFn={getSpecialties}
            selectorFn={selectorSpecialty}
            onChange={handleSelectChange("specialtyId")}
          />

          <OptionsSelect
            isRequired
            defaultValue={
              form.state !== null && form.state !== undefined
                ? {
                    label: form.state === 1 ? "Activo" : "Inactivo",
                    value: form.state.toString(),
                  }
                : { label: "Activo", value: "1" }
            }
            errorMessage={errors?.state as string}
            isInvalid={!!errors?.state}
            label="Estado"
            name="state"
            options={[
              { label: "Activo", value: "1" },
              { label: "Inactivo", value: "0" },
            ]}
            placeholder="Seleccione un estado"
            onChange={handleSelectChange("state")}
          />
        </div>

        <div className="flex gap-4 justify-end mt-4">
          <AsyncButton
            className="font-bold"
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={handleCancel}
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            className="font-bold"
            isLoading={loading}
            loadingText={isEditing ? "Actualizando..." : "Creando..."}
            size="lg"
            type="submit"
            variant="primary"
          >
            {isEditing ? "Actualizar" : "Crear"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

