              cursor: "pointer",
              ":hover": {
                ...base[":hover"],
                borderColor: "transparent",
              },
            }),
            menu: (base) => ({
              ...base,
              borderRadius: "0.5rem",
              backgroundColor: "hsl(var(--heroui-content1))",
              boxShadow: "0px 4px 20px rgba(0, 0, 0, 0.15)",
              zIndex: 9999,
            }),
            menuList: (base) => ({
              ...base,
