import type { ReactNode } from 'react';

interface StepFormProps {
  /** Labels for each step */
  readonly steps: string[];
  /** Zero-based index of the current step */
  readonly currentStep: number;
  readonly onNext: () => void;
  readonly onBack: () => void;
  readonly children: ReactNode;
}

/**
 * Multi-step form wrapper that renders a step indicator bar and
 * Back / Next navigation buttons.
 */
export function StepForm({ steps, currentStep, onNext, onBack, children }: StepFormProps) {
  const isFirst = currentStep === 0;
  const isLast = currentStep === steps.length - 1;

  return (
    <div className="flex flex-col gap-6">
      {/* Step labels */}
      <div className="flex justify-between text-xs font-medium text-gray-500">
        {steps.map((label, index) => (
          <span
            key={label}
            className={`flex-1 text-center ${
              index === currentStep
                ? 'text-blue-600 font-semibold'
                : index < currentStep
                ? 'text-green-600'
                : 'text-gray-400'
            }`}
          >
            {label}
          </span>
        ))}
      </div>

      {/* Step indicator dots */}
      <div className="relative flex items-center">
        {/* Connecting line */}
        <div className="absolute left-0 right-0 top-1/2 h-0.5 -translate-y-1/2 bg-gray-200" />
        <div
          className="absolute left-0 top-1/2 h-0.5 -translate-y-1/2 bg-blue-500 transition-all duration-300"
          style={{
            width:
              steps.length > 1
                ? `${(currentStep / (steps.length - 1)) * 100}%`
                : '0%',
          }}
        />

        {/* Dots */}
        <div className="relative flex w-full justify-between">
          {steps.map((label, index) => (
            <div
              key={label}
              className={`flex h-8 w-8 items-center justify-center rounded-full border-2 text-sm font-bold transition-colors ${
                index < currentStep
                  ? 'border-green-500 bg-green-500 text-white'
                  : index === currentStep
                  ? 'border-blue-500 bg-blue-500 text-white'
                  : 'border-gray-300 bg-white text-gray-400'
              }`}
              aria-current={index === currentStep ? 'step' : undefined}
            >
              {index < currentStep ? 'Ô£ô' : index + 1}
            </div>
          ))}
        </div>
      </div>

      {/* Step content */}
      <div>{children}</div>

      {/* Navigation buttons */}
      <div className="flex justify-between gap-4 pt-2">
        <button
          type="button"
          disabled={isFirst}
          onClick={onBack}
          className={`rounded-md px-5 py-2 text-sm font-semibold transition-colors ${
            isFirst
              ? 'cursor-not-allowed bg-gray-100 text-gray-400'
              : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
          }`}
        >
          Atr├ís
        </button>

        {!isLast && (
          <button
            type="button"
            onClick={onNext}
            className="rounded-md bg-blue-600 px-5 py-2 text-sm font-semibold text-white hover:bg-blue-700 transition-colors"
          >
            Siguiente
          </button>
        )}
      </div>
    </div>
  );
}

interface VitalSignAlertsDisplayProps {
  /** Array of alert messages from useVitalSignAlerts */
  readonly alerts: string[];
}

/**
 * Renders a non-blocking yellow/orange alert panel listing each vital sign alert.
 * Returns null when there are no alerts.
 * Does NOT prevent form submission.
 */
export function VitalSignAlertsDisplay({ alerts }: VitalSignAlertsDisplayProps) {
  if (alerts.length === 0) {
    return null;
  }

  return (
    <div className="rounded-md border border-orange-300 bg-orange-50 p-3">
      <div className="flex items-start gap-2">
        <span className="mt-0.5 text-orange-500" aria-hidden="true">ÔÜá´©Å</span>
        <div className="flex-1">
          <p className="text-sm font-semibold text-orange-800 mb-1">
            Alertas de signos vitales
          </p>
          <ul className="list-disc list-inside space-y-0.5">
            {alerts.map((alert) => (
              <li key={alert} className="text-sm text-orange-700">
                {alert}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}

import axios from "axios";

import {
  ForbiddenError,
  InternalServerError,
  UnauthorizedError,
} from "../../types/errors";
import type { InitialAuth } from "../../types/InitialAuth";
import { API_URL } from "../constants";

export const api = axios.create({
  baseURL: API_URL,
  headers: {
    "Content-Type": "application/json",
    common: {
      Accept: "application/json",
      Authorization: "",
      "Content-Type": "application/json",
    },
    Authorization: "",
  },
});

export const authorization = api.interceptors.response.use(
  async (response) => {
    return response.data;
  },
  (error) => {
    const { response } = error;

    if (response.status === 401) {
      throw new UnauthorizedError(
        "Tu sesi├│n ha expirado vuelve a iniciar sesi├│n",
      );
    } else if (response.status == 400) {
      return response.data;
    } else if (response.status == 403) {
      throw new ForbiddenError(
        "No tienes permisos para realizar esta acci├│n contacta con el administrador",
      );
    } else if (response.status == 500) {
      throw new InternalServerError(
        "Hubo un error en el servidor, Notifica al desarrollador",
      );
    }

    return response.data;
  },
);

api.interceptors.request.use((config) => {
  if (
    config.headers.Authorization === undefined ||
    config.headers.Authorization === "" ||
    config.headers.Authorization === null ||
    config.headers.Authorization === "Bearer " ||
    config.headers.Authorization === "Bearer undefined"
  ) {
    // Determine context: if the current URL is in the portal, prefer patient auth
    const isPortalContext = window.location.pathname.startsWith("/portal");

    if (isPortalContext) {
      // In portal context, try patient auth first
      const storedPatient = window.localStorage.getItem("@patient-auth");
      if (storedPatient) {
        try {
          const parsed = JSON.parse(storedPatient) as { state?: { token?: string }; token?: string };
          const token = parsed?.state?.token ?? parsed?.token;
          if (token) {
            config.headers.Authorization = `Bearer ${token}`;
            return config;
          }
        } catch {
          // Ignore malformed storage
        }
      }
    }

    // Default: try admin auth
    const storedAdmin = window.localStorage.getItem("@auth");
    if (storedAdmin) {
      try {
        const { token }: InitialAuth = JSON.parse(storedAdmin);
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
          return config;
        }
      } catch {
        // Ignore malformed storage
      }
    }

    // Fallback: try patient auth (for non-portal pages that still need patient token)
    if (!isPortalContext) {
      const storedPatient = window.localStorage.getItem("@patient-auth");
      if (storedPatient) {
        try {
          const parsed = JSON.parse(storedPatient) as { state?: { token?: string }; token?: string };
          const token = parsed?.state?.token ?? parsed?.token;
          if (token) {
            config.headers.Authorization = `Bearer ${token}`;
          }
        } catch {
          // Ignore malformed storage
        }
      }
    }
  }

  return config;
});

export const setAuthorization = (token: string) => {
  if (token !== undefined && token !== null && token !== "") {
    api.defaults.headers.common["Authorization"] = `Bearer ${token}`;
    api.defaults.headers.Authorization = `Bearer ${token}`;
  } else {
    api.defaults.headers.common["Authorization"] = "";
    api.defaults.headers.Authorization = "";
  }
};

