import { useCallback, useEffect, useRef, useState } from 'react';

import {
  HubConnection,
  HubConnectionBuilder,
  HubConnectionState,
  LogLevel,
} from '@microsoft/signalr';

import { usePatientAuthStore } from '../stores/usePatientAuthStore';
import type {
  ConnectionState,
  SlotLockInfo,
  SlotLockRejection,
} from '../types/SlotLockTypes';

// ---------------------------------------------------------------------------
// Return type
// ---------------------------------------------------------------------------

export interface UseAppointmentHubReturn {
  /** Current SignalR connection state */
  connectionState: ConnectionState;
  /** Slots locked by OTHER patients ÔÇö key is "HH:mm" */
  lockedSlots: Map<string, SlotLockInfo>;
  /** Permanently confirmed (booked) slots */
  confirmedSlots: Set<string>;
  /** The slot currently locked by the current patient (or null) */
  myLockedSlot: string | null;
  /** Request a lock on a time slot */
  lockSlot: (time: string) => Promise<void>;
  /** Release the currently held lock */
  releaseSlot: (time: string) => Promise<void>;
  /** Last error / rejection message */
  error: string | null;
}

// ---------------------------------------------------------------------------
// Helper: map HubConnectionState ÔåÆ our ConnectionState union
// ---------------------------------------------------------------------------

function toConnectionState(state: HubConnectionState): ConnectionState {
  switch (state) {
    case HubConnectionState.Connected:
      return 'connected';
    case HubConnectionState.Connecting:
      return 'connecting';
    case HubConnectionState.Reconnecting:
      return 'reconnecting';
    default:
      return 'disconnected';
  }
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

/**
 * Manages a SignalR connection to the appointment-booking hub.
 *
 * Handles group subscription (doctor + date), slot lock/release commands,
 * and real-time event listeners for lock state synchronisation.
 *
 * @param doctorId - The doctor whose calendar is being viewed (null = inactive)
 * @param date     - The selected date in "yyyy-MM-dd" format (null = inactive)
 */
export function useAppointmentHub(
  doctorId: number | null,
  date: string | null,
): UseAppointmentHubReturn {
  // ---- state ---------------------------------------------------------------
  const [connectionState, setConnectionState] =
    useState<ConnectionState>('disconnected');
  const [lockedSlots, setLockedSlots] = useState<Map<string, SlotLockInfo>>(
    () => new Map(),
  );
  const [confirmedSlots, setConfirmedSlots] = useState<Set<string>>(
    () => new Set(),
  );
  const [myLockedSlot, setMyLockedSlot] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // ---- refs ----------------------------------------------------------------
  const connectionRef = useRef<HubConnection | null>(null);
  const groupRef = useRef<{ doctorId: number; date: string } | null>(null);
  const myLockedSlotRef = useRef<string | null>(null);

  // Keep the ref in sync so cleanup callbacks always see the latest value.
  useEffect(() => {
    myLockedSlotRef.current = myLockedSlot;
  }, [myLockedSlot]);

  // ---- build connection (once) --------------------------------------------
  useEffect(() => {
    const connection = new HubConnectionBuilder()
      .withUrl('/hubs/appointment-booking', {
        accessTokenFactory: () =>
          usePatientAuthStore.getState().token,
      })
      .withAutomaticReconnect([0, 2000, 5000, 10000, 30000])
      .configureLogging(LogLevel.Warning)
      .build();

    // --- connection lifecycle callbacks ---
    connection.onreconnecting(() => {
      setConnectionState('reconnecting');
    });

    connection.onreconnected(async () => {
      setConnectionState('connected');
      // Re-join the current group and sync state after reconnection
      if (groupRef.current) {
        try {
          await connection.invoke(
            'JoinSlotGroup',
            groupRef.current.doctorId,
            groupRef.current.date,
          );
        } catch {
          // The ActiveLocks event will re-populate state
        }
      }
    });

    connection.onclose(() => {
      setConnectionState('disconnected');
    });

    // --- event listeners ---
    connection.on('ActiveLocks', (locks: SlotLockInfo[]) => {
      const map = new Map<string, SlotLockInfo>();
      for (const lock of locks) {
        map.set(lock.time, lock);
      }
      setLockedSlots(map);
    });

    connection.on('SlotLocked', (info: SlotLockInfo) => {
      setLockedSlots((prev) => {
        const next = new Map(prev);
        next.set(info.time, info);
        return next;
      });
    });

    connection.on('SlotReleased', (info: SlotLockInfo) => {
      setLockedSlots((prev) => {
        const next = new Map(prev);
        next.delete(info.time);
        return next;
      });
    });

    connection.on('SlotLockRejected', (rejection: SlotLockRejection) => {
      setError(rejection.reason);
    });

    connection.on('SlotConfirmed', (info: SlotLockInfo) => {
      setConfirmedSlots((prev) => {
        const next = new Set(prev);
        next.add(info.time);
        return next;
      });
      setLockedSlots((prev) => {
        const next = new Map(prev);
        next.delete(info.time);
        return next;
      });
    });

    connectionRef.current = connection;

    // Cleanup: stop the connection when the hook is destroyed
    return () => {
      const conn = connectionRef.current;
      if (!conn) return;

      const cleanup = async () => {
        try {
          // Release the patient's own lock if any
          if (
            myLockedSlotRef.current &&
            groupRef.current &&
            conn.state === HubConnectionState.Connected
          ) {
            await conn.invoke(
              'ReleaseSlot',
              groupRef.current.doctorId,
              groupRef.current.date,
              myLockedSlotRef.current,
            );
          }

          // Leave the current group
          if (
            groupRef.current &&
            conn.state === HubConnectionState.Connected
          ) {
            await conn.invoke(
              'LeaveSlotGroup',
              groupRef.current.doctorId,
              groupRef.current.date,
            );
          }
        } catch {
          // Best-effort cleanup ÔÇö server will handle disconnection anyway
        } finally {
          await conn.stop();
        }
      };

      cleanup();
      connectionRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ---- start / stop connection based on params ----------------------------
  useEffect(() => {
    const connection = connectionRef.current;
    if (!connection) return;

    if (doctorId != null && date != null) {
      if (connection.state === HubConnectionState.Disconnected) {
        setConnectionState('connecting');
        connection
          .start()
          .then(() => {
            setConnectionState(toConnectionState(connection.state));
          })
          .catch(() => {
            setConnectionState('disconnected');
          });
      }
    } else {
      // Both params are null ÔåÆ disconnect
      if (connection.state !== HubConnectionState.Disconnected) {
        const leaveAndStop = async () => {
          try {
            if (
              groupRef.current &&
              connection.state === HubConnectionState.Connected
            ) {
              if (myLockedSlotRef.current) {
                await connection.invoke(
                  'ReleaseSlot',
                  groupRef.current.doctorId,
                  groupRef.current.date,
                  myLockedSlotRef.current,
                );
              }
              await connection.invoke(
                'LeaveSlotGroup',
                groupRef.current.doctorId,
                groupRef.current.date,
              );
            }
          } catch {
            // best-effort
          } finally {
            groupRef.current = null;
            setMyLockedSlot(null);
            setLockedSlots(new Map());
            setConfirmedSlots(new Set());
            await connection.stop();
            setConnectionState('disconnected');
          }
        };
        leaveAndStop();
      }
    }
  }, [doctorId, date]);

  // ---- group management (join / leave) ------------------------------------
  useEffect(() => {
    const connection = connectionRef.current;
    if (!connection || connection.state !== HubConnectionState.Connected) return;
    if (doctorId == null || date == null) return;

    const prev = groupRef.current;
    const isSameGroup =
      prev != null && prev.doctorId === doctorId && prev.date === date;

    if (isSameGroup) return;

    const switchGroup = async () => {
      try {
        // Leave previous group first
        if (prev) {
          if (myLockedSlotRef.current) {
            await connection.invoke(
              'ReleaseSlot',
              prev.doctorId,
              prev.date,
              myLockedSlotRef.current,
            );
            setMyLockedSlot(null);
          }
          await connection.invoke(
            'LeaveSlotGroup',
            prev.doctorId,
            prev.date,
          );
        }

        // Reset local state for the new group
        setLockedSlots(new Map());
        setConfirmedSlots(new Set());
        setError(null);

        // Join new group
        await connection.invoke('JoinSlotGroup', doctorId, date);
        groupRef.current = { doctorId, date };
      } catch {
        setError('Error al cambiar de grupo. Intente de nuevo.');
      }
    };

    switchGroup();
  }, [doctorId, date, connectionState]);

  // ---- exposed actions ----------------------------------------------------

  const lockSlot = useCallback(async (time: string) => {
    const connection = connectionRef.current;
    const group = groupRef.current;
    if (!connection || !group) return;
    if (connection.state !== HubConnectionState.Connected) return;

    setError(null);
    try {
      await connection.invoke(
        'LockSlot',
        group.doctorId,
        group.date,
        time,
      );
      setMyLockedSlot(time);
    } catch {
      setError('No se pudo bloquear el horario. Intente de nuevo.');
    }
  }, []);

  const releaseSlot = useCallback(async (time: string) => {
    const connection = connectionRef.current;
    const group = groupRef.current;
    if (!connection || !group) return;
    if (connection.state !== HubConnectionState.Connected) return;

    try {
      await connection.invoke(
        'ReleaseSlot',
        group.doctorId,
        group.date,
        time,
      );
      setMyLockedSlot(null);
    } catch {
      setError('No se pudo liberar el horario. Intente de nuevo.');
    }
  }, []);

  return {
    connectionState,
    lockedSlots,
    confirmedSlots,
    myLockedSlot,
    lockSlot,
    releaseSlot,
    error,
  };
}

import { createBrowserRouter, Navigate } from "react-router";

import { nameRoutes } from "../configs/constants";
import { Root } from "../containers/Root";
import { PortalLayout } from "../containers/PortalLayout";
import { ErrorRoutes } from "../routes/ErrorRoutes";
import { PublicRoutes } from "../routes/PublicRoutes";
import { PortalRoutes } from "../routes/PortalRoutes";
import { useAuth } from "./useAuth";
import { getRoleFromToken } from "../utils/jwt";

// Index route: redirect based on role or to portal if not logged in
function RootIndex() {
  const { isLoggedIn, token } = useAuth();

  if (!isLoggedIn) {
    // Check if patient is logged in via patient store
    const patientAuth = window.localStorage.getItem("@patient-auth");
    if (patientAuth) {
      try {
        const parsed = JSON.parse(patientAuth);
        if (parsed?.isLoggedIn && parsed?.token) {
          return <Navigate to={nameRoutes.portalDashboard} replace />;
        }
      } catch { /* ignore */ }
    }
    return <Navigate to={nameRoutes.portalHome} replace />;
  }

  const role = token ? getRoleFromToken(token) : null;

  switch (role) {
    case "Medico":
      return <Navigate to={nameRoutes.doctorDashboard} replace />;
    case "Enfermero":
      return <Navigate to={nameRoutes.nurseDashboard} replace />;
    case "Paciente":
      return <Navigate to={nameRoutes.portalDashboard} replace />;
    default:
      // SA, Recepcionista, Cajero, etc. ÔåÆ admin dashboard
      return <Navigate to={nameRoutes.adminDashboard} replace />;
  }
}

export const useAuthorizationRoutes = () => {
  const { allOperations } = useAuth();

  const routes = createBrowserRouter([
    {
      path: nameRoutes.root,
      element: <Root />,
      children: [
        {
          index: true,
          element: <RootIndex />,
        },
        ...PublicRoutes,
        ...ErrorRoutes,
      ],
    },
    {
      path: nameRoutes.portalHome,
      element: <PortalLayout />,
      children: PortalRoutes,
    },
  ]);

  const operations = new Set(
    allOperations.map((operation) =>
      // Normalize: strip leading slash so "user" matches route path "/user"
      operation.path.toLowerCase().replace(/^\//, ""),
    ),
  );

  const errorPaths = new Set([
    nameRoutes.forbidden,
    nameRoutes.unauthorized,
    nameRoutes.error,
    nameRoutes.notFound,
    nameRoutes.login,
    nameRoutes.changePassword,
    nameRoutes.forgotPassword,
    nameRoutes.resetPassword,
    nameRoutes.register,
    nameRoutes.doctorDashboard,
    nameRoutes.nurseDashboard,
    nameRoutes.adminDashboard,
    nameRoutes.reception,
    nameRoutes.cashier,
    nameRoutes.onlinePayment,
    nameRoutes.doctorManagement,
    nameRoutes.doctorTransfer,
    nameRoutes.appointmentReassign,
    nameRoutes.doctorCalendar,
  ]);

  const routesFiltered = routes.routes[0].children?.filter((route) => {
    if (route.index) return true;
    if (!route.path) return true;
    if (errorPaths.has(route.path)) return true;

    // Normalize route path:
    // 1. Strip leading slash
    // 2. Remove dynamic segments like /:id so "/specialty/update/:id" ÔåÆ "specialty/update"
    const normalizedPath = route.path
      .toLowerCase()
      .replace(/^\//, "")
      .replace(/\/:[^/]+/g, "")   // remove /:param anywhere in the path
      .replace(/:.*$/, "");        // remove :param at the start (edge case)

    if (errorPaths.has(route.path)) return true;
    return operations.has(normalizedPath);
  });

  routes.routes[0].children = routesFiltered as [] | undefined;

  return routes;
};

import { useEffect, useState } from 'react';
import cie10Data from '../data/cie10.json';

export interface Cie10Item {
  code: string;
  description: string;
}

const dataset: Cie10Item[] = cie10Data as Cie10Item[];

/**
 * Searches the bundled CIE-10 dataset with a 300ms debounce.
 * No external API call is made ÔÇö the dataset is a static JSON file.
 *
 * @param query - The search string (matches code or description, case-insensitive)
 * @returns `suggestions` ÔÇö matching CIE-10 items; `isLoading` ÔÇö true during debounce
 */
export function useCie10Autocomplete(query: string): {
  suggestions: Cie10Item[];
  isLoading: boolean;
} {
  const [suggestions, setSuggestions] = useState<Cie10Item[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);

  useEffect(() => {
    const trimmed = query.trim();

    if (!trimmed) {
      setSuggestions([]);
      setIsLoading(false);
      return;
    }

    setIsLoading(true);

    const timer = setTimeout(() => {
      try {
        const lower = trimmed.toLowerCase();
        const results = dataset.filter(
          (item) =>
            item.code.toLowerCase().includes(lower) ||
            item.description.toLowerCase().includes(lower),
        );
        setSuggestions(results.slice(0, 20));
      } catch {
        setSuggestions([]);
      } finally {
        setIsLoading(false);
      }
    }, 300);

    return () => {
      clearTimeout(timer);
    };
  }, [query]);

  return { suggestions, isLoading };
}

import { useCallback, useState } from 'react';
import { generateIdempotencyKey } from '../utils/generateIdempotencyKey';

/**
 * Generates a UUID v4 idempotency key on mount.
 * Call `regenerate()` to get a fresh key for retry scenarios.
 */
export function useIdempotencyKey(): { key: string; regenerate: () => void } {
  const [key, setKey] = useState<string>(() => generateIdempotencyKey());

  const regenerate = useCallback(() => {
    setKey(generateIdempotencyKey());
  }, []);

  return { key, regenerate };
}

/**
 * Provides a Luhn checksum validator for credit/debit card numbers.
 * Accepts digit strings of length 13ÔÇô19 only.
 */
export function useLuhnValidator(): { validate: (cardNumber: string) => boolean } {
  const validate = (cardNumber: string): boolean => {
    // Only accept digit strings of length 13ÔÇô19
    if (!/^\d{13,19}$/.test(cardNumber)) {
      return false;
    }

    // Standard Luhn algorithm
    let sum = 0;
    let shouldDouble = false;

    for (let i = cardNumber.length - 1; i >= 0; i--) {
      let digit = parseInt(cardNumber[i], 10);

      if (shouldDouble) {
        digit *= 2;
        if (digit > 9) {
          digit -= 9;
        }
      }

      sum += digit;
      shouldDouble = !shouldDouble;
    }

    return sum % 10 === 0;
  };

  return { validate };
}

import { useEffect, useRef, useState } from 'react';

/**
 * Countdown timer for payment sessions.
 * Decrements every second and calls `onExpiry` when it reaches zero.
 *
 * @param minutes - Session duration in minutes (typically 10)
 * @param onExpiry - Callback invoked when the session expires
 */
export function usePaymentTimer(
  minutes: number,
  onExpiry: () => void,
): { remaining: number; isExpired: boolean } {
  const [remaining, setRemaining] = useState<number>(minutes * 60);
  const [isExpired, setIsExpired] = useState<boolean>(false);
  const onExpiryRef = useRef(onExpiry);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Keep the callback ref up to date without restarting the interval
  useEffect(() => {
    onExpiryRef.current = onExpiry;
  }, [onExpiry]);

  useEffect(() => {
    const initialSeconds = minutes * 60;
    setRemaining(initialSeconds);
    setIsExpired(false);

    let seconds = initialSeconds;

    intervalRef.current = setInterval(() => {
      seconds -= 1;
      setRemaining(seconds);

      if (seconds <= 0) {
        clearInterval(intervalRef.current!);
        intervalRef.current = null;
        setIsExpired(true);
        onExpiryRef.current();
      }
    }, 1000);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [minutes]);

  return { remaining, isExpired };
}

