/**
 * Validates whether a prescription is still within its 7-day validity window.
 *
 * @param prescriptionDate - ISO date string of when the prescription was issued, or null
 * @returns `isValid` ÔÇö true iff the prescription is 7 days old or less;
 *          `daysOld` ÔÇö number of full days since the prescription date
 */
export function usePrescriptionValidity(
  prescriptionDate: string | null,
): { isValid: boolean; daysOld: number } {
  if (!prescriptionDate) {
    return { isValid: false, daysOld: 0 };
  }

  const issued = new Date(prescriptionDate);
  const today = new Date();

  // Normalise both dates to midnight to count full calendar days
  issued.setHours(0, 0, 0, 0);
  today.setHours(0, 0, 0, 0);

  const diffMs = today.getTime() - issued.getTime();
  const daysOld = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  return {
    isValid: daysOld <= 7,
    daysOld,
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * Countdown timer for appointment reservation slots.
 * Decrements every second and calls `onExpiry` when it reaches zero.
 *
 * @param minutes - Initial duration in minutes
 * @param onExpiry - Callback invoked when the timer reaches zero
 */
export function useReservationTimer(
  minutes: number,
  onExpiry: () => void,
): { remaining: number; isExpired: boolean; reset: () => void } {
  const [remaining, setRemaining] = useState<number>(minutes * 60);
  const [isExpired, setIsExpired] = useState<boolean>(false);
  const onExpiryRef = useRef(onExpiry);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Keep the callback ref up to date without restarting the interval
  useEffect(() => {
    onExpiryRef.current = onExpiry;
  }, [onExpiry]);

  const startInterval = useCallback((initialSeconds: number) => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }

    let seconds = initialSeconds;

    intervalRef.current = setInterval(() => {
      seconds -= 1;
      setRemaining(seconds);

      if (seconds <= 0) {
        clearInterval(intervalRef.current!);
        intervalRef.current = null;
        setIsExpired(true);
        onExpiryRef.current();
      }
    }, 1000);
  }, []);

  useEffect(() => {
    const initialSeconds = minutes * 60;
    setRemaining(initialSeconds);
    setIsExpired(false);
    startInterval(initialSeconds);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [minutes, startInterval]);

  const reset = useCallback(() => {
    setIsExpired(false);
    const initialSeconds = minutes * 60;
    setRemaining(initialSeconds);
    startInterval(initialSeconds);
  }, [minutes, startInterval]);

  return { remaining, isExpired, reset };
}

export interface VitalSignValues {
  bloodPressureSystolic?: number | null;
  bloodPressureDiastolic?: number | null;
  temperature?: number | null;
  heartRate?: number | null;
}

/**
 * Returns an array of alert messages for any vital sign values that fall
 * outside their defined normal ranges. Returns an empty array when all
 * values are within range. Alerts do NOT block form submission.
 *
 * Normal ranges:
 * - Systolic BP:  90ÔÇô140 mmHg
 * - Diastolic BP: 60ÔÇô90 mmHg
 * - Temperature:  36.0ÔÇô37.5 ┬░C
 * - Heart rate:   60ÔÇô100 bpm
 */
export function useVitalSignAlerts(values: VitalSignValues): string[] {
  const alerts: string[] = [];

  const { bloodPressureSystolic, bloodPressureDiastolic, temperature, heartRate } = values;

  if (bloodPressureSystolic != null) {
    if (bloodPressureSystolic < 90) {
      alerts.push('Hipotensi├│n');
    } else if (bloodPressureSystolic > 140) {
      alerts.push('Hipertensi├│n');
    }
  }

  if (bloodPressureDiastolic != null) {
    if (bloodPressureDiastolic < 60) {
      alerts.push('Presi├│n diast├│lica baja');
    } else if (bloodPressureDiastolic > 90) {
      alerts.push('Presi├│n diast├│lica alta');
    }
  }

  if (temperature != null) {
    if (temperature < 36.0) {
      alerts.push('Hipotermia');
    } else if (temperature > 37.5) {
      alerts.push('Fiebre');
    }
  }

  if (heartRate != null) {
    if (heartRate < 60) {
      alerts.push('Bradicardia');
    } else if (heartRate > 100) {
      alerts.push('Taquicardia');
    }
  }

  return alerts;
}

