import { Button } from "@heroui/react";
import { useQuery } from "@tanstack/react-query";
import { useNavigate, useParams } from "react-router";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { getAppointmentById } from "../../services/appointmentService";
import { nameRoutes } from "../../configs/constants";

const statusColors: Record<string, string> = {
  "Pendiente de Pago": "bg-yellow-100 text-yellow-800 border-yellow-200",
  Confirmada: "bg-green-100 text-green-800 border-green-200",
  "Signos Vitales": "bg-purple-100 text-purple-800 border-purple-200",
  "En Espera": "bg-orange-100 text-orange-800 border-orange-200",
  "Consulta M├®dica": "bg-blue-100 text-blue-800 border-blue-200",
  Evaluado: "bg-teal-100 text-teal-800 border-teal-200",
  Laboratorio: "bg-indigo-100 text-indigo-800 border-indigo-200",
  Farmacia: "bg-cyan-100 text-cyan-800 border-cyan-200",
  "Atenci├│n Finalizada": "bg-gray-100 text-gray-700 border-gray-200",
  "No Asisti├│": "bg-red-100 text-red-800 border-red-200",
  Cancelada: "bg-red-100 text-red-800 border-red-200",
};

function DetailRow({ label, value, icon }: { readonly label: string; readonly value: string; readonly icon?: string }) {
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
        {icon && <i className={`bi ${icon} mr-1`} />}
        {label}
      </span>
      <span className="text-sm font-medium text-gray-800 dark:text-gray-100">{value || "ÔÇö"}</span>
    </div>
  );
}

export function AppointmentViewPage() {
  const { id } = useParams();
  const navigate = useNavigate();

  const { data, isLoading, error } = useQuery({
    queryKey: ["appointment-view", id],
    queryFn: () => getAppointmentById(Number(id)),
  });

  if (isLoading) return <LoadingComponent />;

  if (!data?.success || !data.data) {
    return (
      <div className="p-8 text-center text-gray-400">
        <i className="bi bi-exclamation-triangle text-4xl block mb-3" />
        <p>Cita no encontrada. {error instanceof Error ? error.message : ""}</p>
        <Button className="mt-4" variant="secondary" onPress={() => navigate(nameRoutes.appointment)}>
          Volver a Citas
        </Button>
      </div>
    );
  }

  const appt = data.data;
  const statusName = appt.appointmentStatus?.name ?? "";
  const statusClass = statusColors[statusName] ?? "bg-gray-100 text-gray-700 border-gray-200";

  return (
    <div className="max-w-3xl mx-auto p-6">
      <div className="flex items-center gap-3 mb-6">
        <Button size="sm" variant="secondary" onPress={() => navigate(nameRoutes.appointment)}>
          <i className="bi bi-arrow-left mr-1" /> Volver
        </Button>
        <h1 className="text-2xl font-bold">Detalle de Cita #{appt.id}</h1>
      </div>

      {/* Status banner */}
      <div className={`mb-6 rounded-xl border p-4 flex items-center justify-between ${statusClass}`}>
        <div>
          <p className="text-sm font-semibold">Estado actual</p>
          <p className="text-lg font-bold">{statusName || "Desconocido"}</p>
        </div>
        <span className={`px-3 py-1 rounded-full text-sm font-bold border ${statusClass}`}>
          {statusName}
        </span>
      </div>

      {/* Details grid */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-6 mb-6">
        <h2 className="font-bold text-base mb-4">Informaci├│n de la Cita</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-5">
          <DetailRow icon="bi-hash" label="No. Cita" value={String(appt.id)} />
          <DetailRow icon="bi-person" label="Paciente" value={appt.patient?.name ?? `#${appt.patientId}`} />
          <DetailRow icon="bi-person-badge" label="M├®dico" value={appt.doctor?.name ?? (appt.doctorId ? `#${appt.doctorId}` : "Sin asignar")} />
          <DetailRow icon="bi-hospital" label="Especialidad" value={appt.specialty?.name ?? ""} />
          <DetailRow icon="bi-building" label="Sede" value={appt.branch?.name ?? ""} />
          <DetailRow icon="bi-calendar3" label="Fecha y Hora" value={appt.appointmentDate} />
          <DetailRow icon="bi-cash-coin" label="Monto" value={`Q${appt.amount?.toFixed(2) ?? "0.00"}`} />
          <DetailRow icon="bi-flag" label="Prioridad" value={appt.priority > 0 ? "­ƒÜ¿ Emergencia" : "Normal"} />
          {appt.arrivalTime && <DetailRow icon="bi-clock-history" label="Hora de Llegada" value={appt.arrivalTime} />}
        </div>
      </div>

      {/* Reason */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-6 mb-6">
        <h2 className="font-bold text-base mb-2">Motivo de Consulta</h2>
        <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{appt.reason || "Sin motivo registrado."}</p>
      </div>

      {/* Notes */}
      {appt.notes && (
        <div className="bg-white dark:bg-gray-800 rounded-xl border shadow-sm p-6 mb-6">
          <h2 className="font-bold text-base mb-2">Notas</h2>
          <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{appt.notes}</p>
        </div>
      )}

      {/* Metadata */}
      <div className="bg-gray-50 dark:bg-gray-800/50 rounded-xl border p-4 text-xs text-gray-500 grid grid-cols-2 md:grid-cols-4 gap-3">
        <div><span className="font-semibold">Creado:</span> {appt.createdAt}</div>
        <div><span className="font-semibold">Creado por:</span> #{appt.createdBy}</div>
        {appt.updatedAt && <div><span className="font-semibold">Actualizado:</span> {appt.updatedAt}</div>}
        {appt.updatedBy && <div><span className="font-semibold">Actualizado por:</span> #{appt.updatedBy}</div>}
      </div>
    </div>
  );
}

import { toast } from "@heroui/react";
import { useQuery } from "@tanstack/react-query";
import { useCallback, useState } from "react";
import { useNavigate } from "react-router";

import { DynamicCalendar } from "../../components/portal/DynamicCalendar";
import { CatalogueSelect } from "../../components/select/CatalogueSelect";
import { nameRoutes } from "../../configs/constants";
import { useAuth } from "../../hooks/useAuth";
import { createAppointment } from "../../services/appointmentService";
import { getBranches } from "../../services/branchService";
import {
  getDoctorsByBranchAndSpecialty,
  getSpecialtiesByBranch,
} from "../../services/patientPortalService";
import { getUsers } from "../../services/userService";
import type { BranchResponse } from "../../types/BranchResponse";
import type { DoctorResponse } from "../../types/PatientPortalTypes";
import type { SpecialtyResponse } from "../../types/SpecialtyResponse";
import type { UserResponse } from "../../types/UserResponse";
import { formatDateLong, formatTime } from "../../utils/dateFormatter";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------
const CONSULTATION_FEE = 150.0;
const TOTAL_STEPS = 6;

const SPECIALTY_ICONS: Record<string, string> = {
  Cardiologia: "bi-heart-pulse",
  Pediatria: "bi-person-hearts",
  Neurologia: "bi-brain",
  Ortopedia: "bi-bandaid",
  Ginecologia: "bi-gender-female",
  Dermatologia: "bi-droplet",
  Oftalmologia: "bi-eye",
  "Medicina General": "bi-clipboard2-pulse",
};

// ---------------------------------------------------------------------------
// Wizard state
// ---------------------------------------------------------------------------
interface WizardState {
  step: 1 | 2 | 3 | 4 | 5 | 6;
  patient: { id: number; name: string } | null;
  branch: BranchResponse | null;
  specialty: SpecialtyResponse | null;
  doctor: DoctorResponse | null;
  appointmentDate: Date | null;
}

// ---------------------------------------------------------------------------
// StepIndicator
// ---------------------------------------------------------------------------
function StepIndicator({
  current,
  total,
}: {
  readonly current: number;
  readonly total: number;
}) {
  return (
    <div className="mb-8 flex items-center justify-center gap-2">
      {Array.from({ length: total }, (_, i) => {
        const step = i + 1;
        const isActive = step === current;
        const isDone = step < current;
        return (
          <div key={step} className="flex items-center gap-2">
            <div
              className={`flex h-8 w-8 items-center justify-center rounded-full text-sm font-bold transition-colors ${
                isActive
                  ? "bg-blue-600 text-white"
                  : isDone
                    ? "bg-green-500 text-white"
                    : "bg-gray-200 text-gray-500 dark:bg-gray-700 dark:text-gray-400"
              }`}
            >
              {isDone ? <i className="bi bi-check-lg" /> : step}
            </div>
            {step < total && (
              <div
                className={`h-0.5 w-8 ${isDone ? "bg-green-400" : "bg-gray-200 dark:bg-gray-700"}`}
              />
            )}
          </div>
        );
      })}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 1 ÔÇô Select Patient
// ---------------------------------------------------------------------------
function Step1Patient({
  onSelect,
}: {
  readonly onSelect: (patient: { id: number; name: string }) => void;
}) {
  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Seleccione un Paciente
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        Busque y seleccione el paciente para la cita.
      </p>
      <CatalogueSelect<UserResponse>
        isRequired
        deps="Rol.Name:eq:Paciente AND State:eq:1"
        fieldSearch="Name"
        label="Paciente"
        placeholder="Buscar paciente por nombre..."
        queryFn={getUsers}
        selectorFn={(user) => ({
          label: `${user.name} ÔÇö ${user.identificationDocument}`,
          value: String(user.id),
        })}
        onChange={(option) => {
          if (option && "value" in option) {
            onSelect({ id: Number(option.value), name: option.label });
          }
        }}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 2 ÔÇô Select Branch
// ---------------------------------------------------------------------------
function Step2Branch({
  onSelect,
  onBack,
}: {
  readonly onSelect: (branch: BranchResponse) => void;
  readonly onBack: () => void;
}) {
  const { data, isLoading, isError } = useQuery({
    queryKey: ["admin-book-branches"],
    queryFn: () =>
      getBranches({
        pageNumber: 1,
        pageSize: 50,
        filters: "State:eq:1",
        include: null,
        includeTotal: false,
      }),
    staleTime: 1000 * 60 * 10,
  });

  const branches = data?.success ? data.data : [];

  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Seleccione una Sede
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        Elija la sede donde se atender├í el paciente.
      </p>

      {isLoading ? (
        <div className="flex justify-center py-10">
          <i className="bi bi-hourglass-split animate-spin text-3xl text-blue-500" />
        </div>
      ) : null}
      {isError ? (
        <div className="rounded-xl bg-red-50 p-4 text-red-700 dark:bg-red-900/20 dark:text-red-400">
          <i className="bi bi-exclamation-triangle mr-2" />
          Error al cargar sedes. Intente de nuevo.
        </div>
      ) : null}
      {!isLoading && !isError && branches.length === 0 && (
        <p className="text-center text-gray-400">No hay sedes disponibles.</p>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        {branches.map((b) => (
          <button
            key={b.id}
            className="flex items-start gap-4 rounded-xl border border-gray-200 bg-white p-5 text-left shadow-sm transition-all hover:border-blue-400 hover:shadow-md dark:border-gray-700 dark:bg-gray-900/50 dark:hover:border-blue-500"
            type="button"
            onClick={() => onSelect(b)}
          >
            <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-blue-100 dark:bg-blue-900">
              <i className="bi bi-building text-2xl text-blue-600 dark:text-blue-300" />
            </div>
            <div>
              <p className="font-semibold text-gray-800 dark:text-gray-100">
                {b.name}
              </p>
              {b.address ? (
                <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                  <i className="bi bi-geo-alt mr-1" />
                  {b.address}
                </p>
              ) : null}
              {b.phone ? (
                <p className="mt-0.5 text-xs text-gray-500 dark:text-gray-400">
                  <i className="bi bi-telephone mr-1" />
                  {b.phone}
                </p>
              ) : null}
            </div>
            <i className="bi bi-chevron-right ml-auto self-center text-gray-400" />
          </button>
        ))}
      </div>

      <button
        className="mt-6 flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
        type="button"
        onClick={onBack}
      >
        <i className="bi bi-arrow-left" />
        Volver a paciente
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 3 ÔÇô Select Specialty
// ---------------------------------------------------------------------------
function Step3Specialty({
  branchId,
  branchName,
  onSelect,
  onBack,
}: {
  readonly branchId: number;
  readonly branchName: string;
  readonly onSelect: (specialty: SpecialtyResponse) => void;
  readonly onBack: () => void;
}) {
  const { data, isLoading, isError } = useQuery({
    queryKey: ["admin-book-specialties-branch", branchId],
    queryFn: () => getSpecialtiesByBranch(branchId),
    staleTime: 1000 * 60 * 10,
  });

  const specialties = data?.success ? data.data : [];

  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Seleccione una Especialidad
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        Sede: <span className="font-semibold text-blue-600">{branchName}</span>
      </p>

      {isLoading ? (
        <div className="flex justify-center py-10">
          <i className="bi bi-hourglass-split animate-spin text-3xl text-blue-500" />
        </div>
      ) : null}
      {isError ? (
        <div className="rounded-xl bg-red-50 p-4 text-red-700 dark:bg-red-900/20 dark:text-red-400">
          <i className="bi bi-exclamation-triangle mr-2" />
          Error al cargar especialidades. Intente de nuevo.
        </div>
      ) : null}
      {!isLoading && !isError && specialties.length === 0 && (
        <p className="text-center text-gray-400">
          No hay especialidades disponibles en esta sede.
        </p>
      )}

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4">
        {specialties.map((s) => {
          const icon = SPECIALTY_ICONS[s.name] ?? "bi-hospital";
          return (
            <button
              key={s.id}
              className="flex flex-col items-center gap-3 rounded-xl border border-gray-200 bg-white p-5 text-center shadow-sm transition-all hover:border-blue-400 hover:shadow-md dark:border-gray-700 dark:bg-gray-900/50 dark:hover:border-blue-500"
              type="button"
              onClick={() => onSelect(s)}
            >
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-blue-100 dark:bg-blue-900">
                <i
                  className={`bi ${icon} text-2xl text-blue-600 dark:text-blue-300`}
                />
              </div>
              <span className="text-sm font-semibold text-gray-800 dark:text-gray-100">
                {s.name}
              </span>
            </button>
          );
        })}
      </div>

      <button
        className="mt-6 flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
        type="button"
        onClick={onBack}
      >
        <i className="bi bi-arrow-left" />
        Volver a sedes
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 4 ÔÇô Select Doctor
// ---------------------------------------------------------------------------
function Step4Doctor({
  branchId,
  specialtyId,
  specialtyName,
  branchName,
  onSelect,
  onBack,
}: {
  readonly branchId: number;
  readonly specialtyId: number;
  readonly specialtyName: string;
  readonly branchName: string;
  readonly onSelect: (doctor: DoctorResponse) => void;
  readonly onBack: () => void;
}) {
  const { data, isLoading, isError } = useQuery({
    queryKey: ["admin-book-doctors", branchId, specialtyId],
    queryFn: () => getDoctorsByBranchAndSpecialty(branchId, specialtyId),
    staleTime: 1000 * 60 * 5,
  });

  const doctors = data?.success ? data.data : [];

  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Seleccione un M├®dico
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        <span className="font-semibold text-blue-600">{branchName}</span>
        <span className="mx-2 text-gray-300">|</span>
        <span className="font-semibold text-blue-600">{specialtyName}</span>
      </p>

      {isLoading ? (
        <div className="flex justify-center py-10">
          <i className="bi bi-hourglass-split animate-spin text-3xl text-blue-500" />
        </div>
      ) : null}
      {isError ? (
        <div className="rounded-xl bg-red-50 p-4 text-red-700 dark:bg-red-900/20 dark:text-red-400">
          <i className="bi bi-exclamation-triangle mr-2" />
          Error al cargar m├®dicos. Intente de nuevo.
        </div>
      ) : null}
      {!isLoading && !isError && doctors.length === 0 && (
        <p className="text-center text-gray-400">
          No hay m├®dicos disponibles para esta especialidad en esta sede.
        </p>
      )}

      <div className="flex flex-col gap-3">
        {doctors.map((d) => (
          <button
            key={d.id}
            className="flex items-center gap-4 rounded-xl border border-gray-200 bg-white p-4 text-left shadow-sm transition-all hover:border-blue-400 hover:shadow-md dark:border-gray-700 dark:bg-gray-900/50 dark:hover:border-blue-500"
            type="button"
            onClick={() => onSelect(d)}
          >
            <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-cyan-100 dark:bg-cyan-900">
              <i className="bi bi-person-badge text-2xl text-cyan-600 dark:text-cyan-300" />
            </div>
            <div>
              <p className="font-semibold text-gray-800 dark:text-gray-100">
                {d.name}
              </p>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                {d.specialtyName ?? specialtyName}
              </p>
            </div>
            <i className="bi bi-chevron-right ml-auto text-gray-400" />
          </button>
        ))}
      </div>

      <button
        className="mt-6 flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
        type="button"
        onClick={onBack}
      >
        <i className="bi bi-arrow-left" />
        Volver a especialidades
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 5 ÔÇô Select Date / Time
// ---------------------------------------------------------------------------
function Step5Slot({
  doctorId,
  doctorName,
  specialtyName,
  branchName,
  onSelect,
  onBack,
}: {
  readonly doctorId: number;
  readonly doctorName: string;
  readonly specialtyName: string;
  readonly branchName: string;
  readonly onSelect: (dateTime: Date) => void;
  readonly onBack: () => void;
}) {
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);
  const handleSlotSelected = useCallback((dt: Date) => setSelectedSlot(dt), []);

  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Seleccione Fecha y Horario
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        <span className="font-semibold text-blue-600">{branchName}</span>
        <span className="mx-2 text-gray-300">|</span>
        <span className="font-semibold text-blue-600">{specialtyName}</span>
        <span className="mx-2 text-gray-300">|</span>
        <span className="font-semibold text-blue-600">{doctorName}</span>
      </p>

      <div className="mb-4 rounded-xl border border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-900/50">
        <DynamicCalendar
          doctorId={doctorId}
          onSlotSelected={handleSlotSelected}
        />
      </div>

      {selectedSlot ? (
        <p className="mb-4 text-sm font-medium text-green-600">
          <i className="bi bi-check-circle mr-1" />
          Horario seleccionado: {formatDateLong(selectedSlot.toISOString())}
        </p>
      ) : null}

      <div className="flex items-center justify-between">
        <button
          className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
          type="button"
          onClick={onBack}
        >
          <i className="bi bi-arrow-left" />
          Volver a m├®dicos
        </button>
        <button
          className="flex items-center gap-2 rounded-xl bg-blue-600 px-6 py-3 font-bold text-white transition-colors hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
          disabled={!selectedSlot}
          type="button"
          onClick={() => selectedSlot && onSelect(selectedSlot)}
        >
          Continuar
          <i className="bi bi-arrow-right" />
        </button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 6 ÔÇô Reason + Confirm
// ---------------------------------------------------------------------------
interface SummaryData {
  patientName: string;
  patientId: number;
  branchId: number;
  branchName: string;
  specialtyId: number;
  specialtyName: string;
  doctorId: number;
  doctorName: string;
  appointmentDate: Date;
}

function Step6Confirm({
  summary,
  onBack,
  onConfirm,
}: {
  readonly summary: SummaryData;
  readonly onBack: () => void;
  readonly onConfirm: (reason: string) => Promise<void>;
}) {
  const [reason, setReason] = useState("");
  const [reasonError, setReasonError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [apiError, setApiError] = useState("");

  const handleSubmit = useCallback(async () => {
    setReasonError("");
    setApiError("");

    if (reason.trim().length < 10) {
      setReasonError("El motivo debe tener al menos 10 caracteres.");
      return;
    }
    if (reason.trim().length > 2000) {
      setReasonError("El motivo no puede superar 2000 caracteres.");
      return;
    }

    setIsSubmitting(true);
    try {
      await onConfirm(reason.trim());
    } catch (err: unknown) {
      setApiError(
        err instanceof Error ? err.message : "Error al confirmar la cita.",
      );
    } finally {
      setIsSubmitting(false);
    }
  }, [reason, onConfirm]);

  const formattedDate = formatDateLong(summary.appointmentDate.toISOString());
  const formattedTime = formatTime(summary.appointmentDate.toISOString());

  return (
    <div>
      <h2 className="mb-1 text-xl font-bold text-gray-800 dark:text-gray-100">
        Confirmar Cita
      </h2>
      <p className="mb-6 text-sm text-gray-500 dark:text-gray-400">
        Revise los detalles y proporcione el motivo de la consulta.
      </p>

      {/* Summary card */}
      <div className="mb-6 rounded-xl border border-blue-100 bg-blue-50 p-5 dark:border-blue-800 dark:bg-blue-900/20">
        <h3 className="mb-3 font-bold text-blue-800 dark:text-blue-300">
          <i className="bi bi-clipboard2-check mr-2" />
          Resumen de la Cita
        </h3>
        <dl className="grid grid-cols-1 gap-2 text-sm sm:grid-cols-2">
          <div>
            <dt className="text-gray-500 dark:text-gray-400">Paciente</dt>
            <dd className="font-semibold text-gray-800 dark:text-gray-100">
              {summary.patientName}
            </dd>
          </div>
          <div>
            <dt className="text-gray-500 dark:text-gray-400">Sede</dt>
            <dd className="font-semibold text-gray-800 dark:text-gray-100">
              {summary.branchName}
            </dd>
          </div>
          <div>
            <dt className="text-gray-500 dark:text-gray-400">Especialidad</dt>
            <dd className="font-semibold text-gray-800 dark:text-gray-100">
              {summary.specialtyName}
            </dd>
          </div>
          <div>
            <dt className="text-gray-500 dark:text-gray-400">M├®dico</dt>
            <dd className="font-semibold text-gray-800 dark:text-gray-100">
              {summary.doctorName}
            </dd>
          </div>
          <div>
            <dt className="text-gray-500 dark:text-gray-400">Fecha</dt>
            <dd className="font-semibold text-gray-800 dark:text-gray-100">
              {formattedDate}
            </dd>
          </div>
          <div>
            <dt className="text-gray-500 dark:text-gray-400">Hora</dt>
            <dd className="font-semibold text-gray-800 dark:text-gray-100">
              {formattedTime}
            </dd>
          </div>
          <div>
            <dt className="text-gray-500 dark:text-gray-400">Honorario</dt>
            <dd className="font-bold text-blue-700 dark:text-blue-300">
              Q{CONSULTATION_FEE.toFixed(2)}
            </dd>
          </div>
        </dl>
      </div>

      {/* Reason textarea */}
      <div className="mb-6 flex flex-col gap-1">
        <label
          className="text-sm font-bold text-gray-700 dark:text-gray-300"
          htmlFor="reason"
        >
          Motivo de la Consulta *
        </label>
        <textarea
          className={`w-full resize-none rounded-xl border px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white ${
            reasonError
              ? "border-red-400 bg-red-50 dark:bg-red-900/20"
              : "border-gray-300 dark:border-gray-600"
          }`}
          id="reason"
          maxLength={2000}
          minLength={10}
          placeholder="Describa brevemente el motivo de la consulta (m├¡nimo 10 caracteres)..."
          rows={4}
          value={reason}
          onChange={(e) => {
            setReason(e.target.value);
            setReasonError("");
          }}
        />
        <div className="flex justify-between">
          {reasonError ? (
            <p className="text-xs text-red-500">
              <i className="bi bi-exclamation-circle mr-1" />
              {reasonError}
            </p>
          ) : (
            <span />
          )}
          <span className="text-xs text-gray-400">{reason.length}/2000</span>
        </div>
      </div>

      {/* API error */}
      {apiError ? (
        <div className="mb-4 rounded-xl border border-red-300 bg-red-50 p-4 text-sm text-red-800 dark:border-red-700 dark:bg-red-900/20 dark:text-red-300">
          <i className="bi bi-exclamation-triangle-fill mr-2" />
          {apiError}
        </div>
      ) : null}

      {/* Actions */}
      <div className="flex items-center justify-between">
        <button
          className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
          disabled={isSubmitting}
          type="button"
          onClick={onBack}
        >
          <i className="bi bi-arrow-left" />
          Volver
        </button>
        <button
          className="flex items-center gap-2 rounded-xl bg-green-600 px-6 py-3 font-bold text-white transition-colors hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-50"
          disabled={isSubmitting}
          type="button"
          onClick={() => void handleSubmit()}
        >
          {isSubmitting ? (
            <>
              <i className="bi bi-hourglass-split animate-spin" />
              Confirmando...
            </>
          ) : (
            <>
              <i className="bi bi-check-circle" />
              Confirmar Cita
            </>
          )}
        </button>
      </div>
    </div>
  );
}

