// ---------------------------------------------------------------------------
export function CreateAppointmentPage() {
  const navigate = useNavigate();
  const { userId } = useAuth();

  const [wizard, setWizard] = useState<WizardState>({
    step: 1,
    patient: null,
    branch: null,
    specialty: null,
    doctor: null,
    appointmentDate: null,
  });

  const [slotConflictError, setSlotConflictError] = useState(false);

  // -- handlers ---------------------------------------------------------------
  const handlePatientSelect = useCallback(
    (patient: { id: number; name: string }) =>
      setWizard((prev) => ({ ...prev, step: 2, patient })),
    [],
  );

  const handleBranchSelect = useCallback(
    (branch: BranchResponse) =>
      setWizard((prev) => ({ ...prev, step: 3, branch })),
    [],
  );

  const handleSpecialtySelect = useCallback(
    (specialty: SpecialtyResponse) =>
      setWizard((prev) => ({ ...prev, step: 4, specialty })),
    [],
  );

  const handleDoctorSelect = useCallback(
    (doctor: DoctorResponse) =>
      setWizard((prev) => ({ ...prev, step: 5, doctor })),
    [],
  );

  const handleSlotSelect = useCallback((dateTime: Date) => {
    setSlotConflictError(false);
    setWizard((prev) => ({ ...prev, step: 6, appointmentDate: dateTime }));
  }, []);

  const handleConfirm = useCallback(
    async (reason: string) => {
      if (
        !wizard.patient ||
        !wizard.branch ||
        !wizard.specialty ||
        !wizard.doctor ||
        !wizard.appointmentDate
      ) {
        throw new Error(
          "Datos incompletos. Por favor, complete todos los pasos.",
        );
      }

      const response = await createAppointment({
        patientId: wizard.patient.id,
        doctorId: wizard.doctor.id,
        specialtyId: wizard.specialty.id,
        branchId: wizard.branch.id,
        appointmentDate: wizard.appointmentDate.toISOString(),
        reason,
        amount: CONSULTATION_FEE,
        state: 1,
        createdBy: userId,
      });

      if (response.success) {
        toast.success("Cita agendada correctamente");
        navigate(nameRoutes.appointment);
      } else {
        const isConflict =
          response.message?.toLowerCase().includes("disponible") ||
          response.message?.toLowerCase().includes("ocupado") ||
          response.message?.toLowerCase().includes("409");

        if (isConflict) {
          setSlotConflictError(true);
          setWizard((prev) => ({ ...prev, step: 5 }));
          throw new Error("El horario seleccionado ya no est├í disponible");
        }

        throw new Error(
          response.message ?? "Error al confirmar la cita. Intente de nuevo.",
        );
      }
    },
    [wizard, userId, navigate],
  );

  // -- render -----------------------------------------------------------------
  return (
    <section className="min-h-[calc(100vh-140px)] bg-gray-50 px-4 py-10 dark:bg-gray-900">
      <div className="mx-auto max-w-3xl">
        {/* Header */}
        <div className="mb-6 text-center">
          <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
            <i className="bi bi-calendar-plus mr-2 text-blue-600" />
            Crear Nueva Cita
          </h1>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
            Complete los pasos para agendar una cita desde el panel
            administrativo.
          </p>
        </div>

        <StepIndicator current={wizard.step} total={TOTAL_STEPS} />

        {/* Slot conflict banner */}
        {slotConflictError ? (
          <div className="mb-6 rounded-xl border border-red-300 bg-red-50 p-4 text-sm text-red-800 dark:border-red-700 dark:bg-red-900/20 dark:text-red-300">
            <i className="bi bi-exclamation-triangle-fill mr-2" />
            El horario seleccionado ya no est├í disponible. Por favor, elija otro
            horario.
          </div>
        ) : null}

        {/* Wizard card */}
        <div className="rounded-2xl border border-gray-100 bg-white p-6 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          {wizard.step === 1 && <Step1Patient onSelect={handlePatientSelect} />}

          {wizard.step === 2 && (
            <Step2Branch
              onBack={() => setWizard((prev) => ({ ...prev, step: 1 }))}
              onSelect={handleBranchSelect}
            />
          )}

          {wizard.step === 3 && wizard.branch ? (
            <Step3Specialty
              branchId={wizard.branch.id}
              branchName={wizard.branch.name}
              onBack={() => setWizard((prev) => ({ ...prev, step: 2 }))}
              onSelect={handleSpecialtySelect}
            />
          ) : null}

          {wizard.step === 4 && wizard.branch && wizard.specialty ? (
            <Step4Doctor
              branchId={wizard.branch.id}
              branchName={wizard.branch.name}
              specialtyId={wizard.specialty.id}
              specialtyName={wizard.specialty.name}
              onBack={() => setWizard((prev) => ({ ...prev, step: 3 }))}
              onSelect={handleDoctorSelect}
            />
          ) : null}

          {wizard.step === 5 &&
          wizard.doctor &&
          wizard.specialty &&
          wizard.branch ? (
            <Step5Slot
              branchName={wizard.branch.name}
              doctorId={wizard.doctor.id}
              doctorName={wizard.doctor.name}
              specialtyName={wizard.specialty.name}
              onBack={() => setWizard((prev) => ({ ...prev, step: 4 }))}
              onSelect={handleSlotSelect}
            />
          ) : null}

          {wizard.step === 6 &&
          wizard.patient &&
          wizard.branch &&
          wizard.specialty &&
          wizard.doctor &&
          wizard.appointmentDate ? (
            <Step6Confirm
              summary={{
                patientId: wizard.patient.id,
                patientName: wizard.patient.name,
                branchId: wizard.branch.id,
                branchName: wizard.branch.name,
                specialtyId: wizard.specialty.id,
                specialtyName: wizard.specialty.name,
                doctorId: wizard.doctor.id,
                doctorName: wizard.doctor.name,
                appointmentDate: wizard.appointmentDate,
              }}
              onBack={() => setWizard((prev) => ({ ...prev, step: 5 }))}
              onConfirm={handleConfirm}
            />
          ) : null}
        </div>
      </div>
    </section>
  );
}

import { Button, toast } from "@heroui/react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback } from "react";
import { useNavigate, useParams } from "react-router";
import { AppointmentForm } from "../../components/form/AppointmentForm";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { getAppointmentById, updateAppointment } from "../../services/appointmentService";
import type { AppointmentRequest } from "../../types/AppointmentResponse";
import { nameRoutes } from "../../configs/constants";
import { validationFailureToString } from "../../utils/converted";

export function UpdateAppointmentPage() {
  const { id } = useParams();
  const client = useQueryClient();
  const navigate = useNavigate();

  const { data, isLoading, error } = useQuery({
    queryKey: ["appointmentToUpdate", id],
    queryFn: () => getAppointmentById(Number(id)),
  });

  const onSubmit = useCallback(
    async (form: AppointmentRequest) => {
      const response = await updateAppointment(form);
      if (!response.success) { toast.danger(`${response.message} ${validationFailureToString(response.data)}`); return response; }
      await client.invalidateQueries({ queryKey: ["appointments"] });
      await client.invalidateQueries({ queryKey: ["appointmentToUpdate", id] });
      toast.success("Cita actualizada correctamente");
      return response;
    },
    [client, id],
  );

  if (isLoading) return <LoadingComponent />;

  return (
    <div>
      {data?.success ? (
        <>
          {data.data.appointmentStatus?.name === "Pagada" && (
            <div className="max-w-3xl mx-auto px-4 pt-4 flex justify-end">
              <Button
                size="sm"
                variant="secondary"
                onPress={() => navigate(`${nameRoutes.appointmentReassign}?appointmentId=${id}`)}
              >
                <i className="bi bi-person-check mr-2" />
                Reasignar M├®dico
              </Button>
            </div>
          )}
          <AppointmentForm initialForm={data.data} type="edit" onSubmit={onSubmit} />
        </>
      ) : (
        <div>Error: {error instanceof Error ? error.message : "Error desconocido"}</div>
      )}
    </div>
  );
}

import { Label, TextField } from "@heroui/react";
import type { ChangeEvent } from "react";
import { useCallback } from "react";
import { Col } from "../../components/grid/Col";
import { AsyncButton } from "../../components/button/AsyncButton";
import { Response } from "../../components/messages/Response";
import { TimezoneSelector } from "../../components/select/TimezoneSelector";
import { useAuth } from "../../hooks/useAuth";
import { useForm } from "../../hooks/useForm";
import ProtectedPublic from "../../routes/middlewares/ProtectedPublic";
import { changePassword } from "../../services/authService";
import { validateChangePassword } from "../../validations/changePasswordValidation";

export interface ChangePasswordForm {
  idUser: number;
  password: string;
  confirmPassword: string;
}

const initialForm: ChangePasswordForm = {
  idUser: 0,
  password: "",
  confirmPassword: "",
};

export function Component() {
  const { userId, logout } = useAuth();

  const sendForm = async (form: ChangePasswordForm) => {
    form.idUser = userId;
    const response = await changePassword(form);
    if (response.success) {
      logout();
    }
    return response;
  };

  const { form, handleChange, handleSubmit, success, message, loading } = useForm(
    initialForm,
    validateChangePassword,
    sendForm,
  );

  const handlePasswordChange = useCallback(
    (val: string) => {
      handleChange({
        target: { name: "password", value: val },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleConfirmPasswordChange = useCallback(
    (val: string) => {
      handleChange({
        target: { name: "confirmPassword", value: val },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  return (
    <ProtectedPublic>
      <div className="page-view container flex flex-col flex-wrap items-center justify-center">
        <Col lg={8} md={10} sm={12} xl={6}>
          {success != null && <Response message={message} type={success} />}
          <h1 className="text-center text-4xl font-bold">Cambiar contrase├▒a</h1>
        </Col>
        <form
          className="flex flex-row flex-wrap justify-center col-xl-6 col-lg-8 col-md-10 col-12"
          onSubmit={handleSubmit}
        >
          <Col md={12}>
            <Label className="font-bold">Contrase├▒a</Label>
            <TextField
              isRequired
              className="py-4"
              name="password"
              type="password"
              value={form.password}
              onChange={handlePasswordChange}
            />
          </Col>
          <Col md={12}>
            <Label className="font-bold">Confirmacion de contrase├▒a</Label>
            <TextField
              isRequired
              className="py-4"
              name="confirmPassword"
              type="password"
              value={form.confirmPassword}
              onChange={handleConfirmPasswordChange}
            />
          </Col>
          <Col className="mt-5" md={12}>
            <AsyncButton
              className="py-4 mt-4 font-bold w-full"
              isLoading={loading}
              loadingText="Cambiando contrase├▒a..."
              size="lg"
              type="submit"
              variant="primary"
            >
              Cambiar contrase├▒a
            </AsyncButton>
          </Col>
        </form>
        {/* Timezone preference */}
        <Col className="mt-8" lg={8} md={10} sm={12} xl={6}>
          <h2 className="text-center text-2xl font-bold mb-4">Preferencias</h2>
          <TimezoneSelector userId={userId} />
        </Col>
      </div>
    </ProtectedPublic>
  );
}

Component.displayName = "ChangePasswordPage";

import { useState, useCallback, type FormEvent } from "react";
import { Link } from "react-router";
import { z } from "zod";

import { nameRoutes } from "../../configs/constants";
import { recoveryPassword } from "../../services/authService";

const emailSchema = z.object({
  email: z.string().min(1, "El correo es requerido").email("Ingrese un correo v├ílido"),
});

interface ForgotPasswordPageProps {
  /** Where to link "back to login" ÔÇö defaults to admin login */
  readonly loginRoute?: string;
}

export function ForgotPasswordPage({ loginRoute = nameRoutes.login }: ForgotPasswordPageProps) {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSubmit = useCallback(
    async (e: FormEvent) => {
      e.preventDefault();
      setError("");

      const result = emailSchema.safeParse({ email });
      if (!result.success) {
        setError(result.error.issues[0].message);
        return;
      }

      setIsLoading(true);
      try {
        const response = await recoveryPassword(email.trim());
        if (response.success) {
          setSent(true);
        } else {
          // Always show generic message to prevent email enumeration
          setSent(true);
        }
      } catch {
        setError("No se pudo conectar con el servidor. Intente de nuevo m├ís tarde.");
      } finally {
        setIsLoading(false);
      }
    },
    [email],
  );

  return (
    <section className="flex items-center justify-center min-h-[calc(100vh-140px)] px-4 py-12">
      <div className="w-full max-w-md">
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700 p-8">
          <div className="flex justify-center mb-4">
            <div className="flex items-center justify-center w-16 h-16 rounded-full bg-blue-100 dark:bg-blue-900/30">
              <i className="bi bi-envelope-at text-3xl text-blue-600" />
            </div>
          </div>

          <h1 className="text-2xl font-bold text-center text-gray-800 dark:text-gray-100 mb-1">
            Recuperar Contrase├▒a
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 text-center mb-6">
            Ingrese su correo electr├│nico y le enviaremos un enlace para restablecer su contrase├▒a.
          </p>

          {sent ? (
            <div className="text-center">
              <div className="mb-4 p-4 bg-green-50 border border-green-300 rounded-xl text-green-800 text-sm dark:bg-green-900/20 dark:border-green-700 dark:text-green-300">
                <i className="bi bi-check-circle-fill mr-2" />
                Si el correo est├í registrado, recibir├í un enlace de recuperaci├│n. Revise su bandeja de entrada y la carpeta de spam.
              </div>
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                El enlace es v├ílido por 15 minutos.
              </p>
              <Link
                to={loginRoute}
                className="text-sm font-bold text-blue-600 hover:text-blue-700 dark:text-blue-400 underline"
              >
                <i className="bi bi-arrow-left mr-1" />
                Volver al inicio de sesi├│n
              </Link>
            </div>
          ) : (
            <>
              {error && (
                <div className="mb-4 p-4 bg-red-50 border border-red-300 rounded-xl text-red-800 text-sm flex items-start gap-2 dark:bg-red-900/20 dark:border-red-700 dark:text-red-300">
                  <i className="bi bi-exclamation-triangle-fill mt-0.5 shrink-0" />
                  <span>{error}</span>
                </div>
              )}

              <form onSubmit={handleSubmit} className="flex flex-col gap-4" noValidate>
                <div className="flex flex-col gap-1">
                  <label htmlFor="recovery-email" className="text-sm font-bold text-gray-700 dark:text-gray-300">
                    Correo Electr├│nico *
                  </label>
                  <input
                    id="recovery-email"
                    autoComplete="email"
                    className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white transition-colors"
                    placeholder="usuario@dominio.com"
                    type="email"
                    value={email}
                    onChange={(e) => { setEmail(e.target.value); setError(""); }}
                  />
                </div>

                <button
                  className="w-full py-3 mt-2 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold rounded-xl transition-colors flex items-center justify-center gap-2"
                  disabled={isLoading}
                  type="submit"
                >
                  {isLoading ? (
                    <>
                      <i className="bi bi-hourglass-split animate-spin" />
                      Enviando...
                    </>
                  ) : (
                    <>
                      <i className="bi bi-send" />
                      Enviar Enlace de Recuperaci├│n
                    </>
                  )}
                </button>
              </form>

              <div className="text-center mt-6">
                <Link
                  to={loginRoute}
                  className="text-sm text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400"
                >
                  <i className="bi bi-arrow-left mr-1" />
                  Volver al inicio de sesi├│n
                </Link>
              </div>
            </>
          )}
        </div>
      </div>
    </section>
  );
}

/** Admin forgot password wrapper */
export function AdminForgotPasswordPage() {
  return <ForgotPasswordPage loginRoute={nameRoutes.login} />;
}

/** Portal forgot password wrapper */
export function PortalForgotPasswordPage() {
  return <ForgotPasswordPage loginRoute={nameRoutes.portalLogin} />;
}

export default ForgotPasswordPage;

