import { Card, FieldError, Form, Input, Label, TextField, toast } from "@heroui/react";
import { useCallback, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import { AsyncButton } from "../../components/button/AsyncButton";
import { Response } from "../../components/messages/Response";
import { useForm } from "../../hooks/useForm";
import { LogoHIS } from "../../components/brand/LogoHIS";
import { api } from "../../configs/axios/interceptors";
import type { ApiResponse } from "../../types/ApiResponse";
import type { RegisterFormData } from "../../validations/registerValidation";
import { validateRegister } from "../../validations/registerValidation";

const initialForm: RegisterFormData = {
  name: "",
  identificationDocument: "",
  userName: "",
  password: "",
  email: "",
  number: "",
  nit: "",
  insuranceNumber: "",
};

export function RegisterPage() {
  const navigate = useNavigate();

  const petition = useCallback(async (form: RegisterFormData): Promise<ApiResponse<unknown>> => {
    const response = await api.post<unknown, ApiResponse<unknown>, RegisterFormData & { state: number; createdBy: null }>(
      "/Auth/Register",
      { ...form, state: 1, createdBy: null },
    );

    if (response.success) {
      toast.success("┬íRegistro exitoso! Bienvenido(a). Ahora puede agendar su cita.");
      setTimeout(() => navigate("/appointment/create"), 2000);
    }

    return response;
  }, [navigate]);

  const { form, errors, handleChange, handleSubmit, success, message, loading } =
    useForm<RegisterFormData, unknown>(initialForm, validateRegister, petition, true);

  const handleTextChange = useCallback(
    (name: string) => (val: string) => {
      handleChange({ target: { name, value: val } } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  return (
    <section className="flex flex-col md:flex-row justify-center items-center w-screen min-h-screen login-bg relative overflow-hidden py-8">
      <div className="flex items-center px-6 md:mx-auto w-full md:max-w-2xl">
        <Card className="w-full shadow-[0px_20px_20px_10px_#A0AEC0] login-card">
          <div className="p-8 flex flex-col w-full">
            <div className="flex justify-center mb-6">
              <LogoHIS height="auto" width="160px" />
            </div>
            <h1 className="text-2xl font-bold text-center mb-2">Registro de Paciente</h1>
            <p className="text-gray-500 text-sm text-center mb-6">
              Complete sus datos para registrarse y agendar citas m├®dicas.
            </p>

            {success != null && <Response message={message} type={success} />}

            <Form className="flex flex-col gap-4" validationErrors={errors} onSubmit={handleSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <TextField isRequired className="flex flex-col gap-1 md:col-span-2" isInvalid={!!errors?.name} name="name" onChange={handleTextChange("name")}>
                  <Label className="font-bold">Nombre Completo *</Label>
                  <Input className="px-3 py-2 border rounded-md" type="text" value={form.name} placeholder="M├¡nimo 10 caracteres" />
                  {errors?.name ? <FieldError>{errors.name as string}</FieldError> : null}
                </TextField>

                <TextField isRequired className="flex flex-col gap-1" isInvalid={!!errors?.identificationDocument} name="identificationDocument" onChange={handleTextChange("identificationDocument")}>
                  <Label className="font-bold">DPI * (13 d├¡gitos)</Label>
                  <Input className="px-3 py-2 border rounded-md" type="text" maxLength={13} value={form.identificationDocument} placeholder="1234567890123" />
                  {errors?.identificationDocument ? <FieldError>{errors.identificationDocument as string}</FieldError> : null}
                </TextField>

                <TextField isRequired className="flex flex-col gap-1" isInvalid={!!errors?.number} name="number" onChange={handleTextChange("number")}>
                  <Label className="font-bold">Tel├®fono * (8 d├¡gitos)</Label>
                  <Input className="px-3 py-2 border rounded-md" type="tel" maxLength={8} value={form.number} placeholder="55551234" />
                  {errors?.number ? <FieldError>{errors.number as string}</FieldError> : null}
                </TextField>

                <TextField isRequired className="flex flex-col gap-1 md:col-span-2" isInvalid={!!errors?.email} name="email" onChange={handleTextChange("email")}>
                  <Label className="font-bold">Correo Electr├│nico *</Label>
                  <Input className="px-3 py-2 border rounded-md" type="email" value={form.email} placeholder="usuario@dominio.com" />
                  {errors?.email ? <FieldError>{errors.email as string}</FieldError> : null}
                </TextField>

                <TextField isRequired className="flex flex-col gap-1" isInvalid={!!errors?.userName} name="userName" onChange={handleTextChange("userName")}>
                  <Label className="font-bold">Nombre de Usuario * (8-9 chars)</Label>
                  <Input className="px-3 py-2 border rounded-md" type="text" minLength={8} maxLength={9} value={form.userName} placeholder="miusuario" />
                  {errors?.userName ? <FieldError>{errors.userName as string}</FieldError> : null}
                </TextField>

                <TextField isRequired className="flex flex-col gap-1" isInvalid={!!errors?.password} name="password" onChange={handleTextChange("password")}>
                  <Label className="font-bold">Contrase├▒a * (m├¡n. 12 chars)</Label>
                  <Input className="px-3 py-2 border rounded-md" type="password" value={form.password} placeholder="M├¡nimo 12 caracteres" />
                  {errors?.password ? <FieldError>{errors.password as string}</FieldError> : null}
                </TextField>

                <TextField className="flex flex-col gap-1" isInvalid={!!errors?.nit} name="nit" onChange={handleTextChange("nit")}>
                  <Label className="font-bold">NIT (8-9 chars, opcional)</Label>
                  <Input className="px-3 py-2 border rounded-md" type="text" value={form.nit || ""} placeholder="12345678" />
                  {errors?.nit ? <FieldError>{errors.nit as string}</FieldError> : null}
                </TextField>

                <TextField className="flex flex-col gap-1" isInvalid={!!errors?.insuranceNumber} name="insuranceNumber" onChange={handleTextChange("insuranceNumber")}>
                  <Label className="font-bold">No. Seguro M├®dico (opcional)</Label>
                  <Input className="px-3 py-2 border rounded-md" type="text" value={form.insuranceNumber || ""} placeholder="N├║mero de afiliado" />
                  {errors?.insuranceNumber ? <FieldError>{errors.insuranceNumber as string}</FieldError> : null}
                </TextField>
              </div>

              <AsyncButton
                className="py-3 mt-2 font-bold w-full"
                isLoading={loading}
                loadingText="Registrando..."
                size="lg"
                type="submit"
                variant="primary"
              >
                <i className="bi bi-person-plus mr-2" /> Registrarse
              </AsyncButton>
            </Form>

            <div className="flex flex-col items-center mt-4 gap-2 text-sm">
              <span className="text-gray-500">┬┐Ya tiene cuenta?</span>
              <button
                className="font-bold underline text-cyan-500"
                type="button"
                onClick={() => navigate("/auth")}
              >
                Iniciar Sesi├│n
              </button>
            </div>
          </div>
        </Card>
      </div>
    </section>
  );
}

export function Component() {
  return <RegisterPage />;
}
Component.displayName = "RegisterPage";

import { Button, toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { useNavigate } from "react-router";
import { ReceptionSearch } from "../../components/reception/ReceptionSearch";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { getAppointments, partialUpdateAppointment } from "../../services/appointmentService";
import type { AppointmentResponse } from "../../types/AppointmentResponse";

const statusColors: Record<string, string> = {
  Pagada: "bg-green-100 text-green-800 border-green-300",
  Pendiente: "bg-yellow-100 text-yellow-800 border-yellow-300",
  Cancelada: "bg-red-100 text-red-800 border-red-300",
  "En curso": "bg-blue-100 text-blue-800 border-blue-300",
  Completada: "bg-gray-100 text-gray-800 border-gray-300",
  "No asisti├│": "bg-orange-100 text-orange-800 border-orange-300",
  "Paciente presente": "bg-purple-100 text-purple-800 border-purple-300",
};

export function ReceptionPage() {
  const [searchQuery, setSearchQuery] = useState("");
  const [searchType, setSearchType] = useState<"dpi" | "id">("dpi");
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ["reception-search", searchQuery, searchType],
    queryFn: () => {
      if (!searchQuery) return Promise.resolve({ success: true as const, data: [], message: "", totalResults: 0 });
      const filter = searchType === "dpi"
        ? `Patient.IdentificationDocument:eq:${searchQuery}`
        : `Id:eq:${searchQuery}`;
      return getAppointments({
        pageNumber: 1,
        pageSize: 20,
        filters: `${filter} AND State:eq:1`,
        include: "Specialty,Branch,AppointmentStatus,Patient",
        includeTotal: false,
      });
    },
    enabled: !!searchQuery,
  });

  const registerArrivalMutation = useMutation({
    mutationFn: async (appointment: AppointmentResponse) => {
      return partialUpdateAppointment({
        id: appointment.id,
        arrivalTime: new Date().toISOString(),
      });
    },
    onSuccess: (_data, appointment) => {
      const patientName = appointment.patient?.name ?? `Paciente #${appointment.patientId}`;
      if (appointment.priority > 0) {
        toast.success(`Paciente ${patientName} registrado con prioridad de EMERGENCIA. El paciente debe pasar directamente a toma de signos vitales.`);
      } else {
        toast.success(`La llegada del paciente ${patientName} ha sido registrada exitosamente. El paciente debe pasar a la sala de espera.`);
      }
      queryClient.invalidateQueries({ queryKey: ["reception-search"] });
    },
    onError: () => toast.danger("Error al registrar la llegada"),
  });

  const appointments = data?.success ? data.data : [];

  return (
    <div className="max-w-5xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-2">Recepci├│n y Verificaci├│n de Citas</h1>
      <p className="text-gray-500 text-sm mb-6">Busque al paciente por DPI o n├║mero de cita para verificar y registrar su llegada.</p>

      {/* Buscador */}
      <ReceptionSearch
        onSearch={(query, type) => {
          setSearchType(type);
          setSearchQuery(query);
        }}
      />

      {/* Resultados */}
      {isLoading && <LoadingComponent />}

      {!isLoading && searchQuery && appointments.length === 0 && (
        <div className="text-center py-12 text-gray-400">
          <i className="bi bi-search text-4xl block mb-3" />
          <p className="text-gray-600 dark:text-gray-300">No se encontraron citas activas para el paciente.</p>
          <p className="text-sm mt-1">El paciente no se encuentra registrado en el sistema o no tiene citas activas. Verifique los datos e intente nuevamente.</p>
          <div className="flex gap-3 justify-center mt-4">
            <Button variant="primary" onPress={() => navigate("/appointment/create")}>
              <i className="bi bi-plus-circle mr-2" /> Nueva Cita (Walk-in)
            </Button>
            <Button variant="secondary" onPress={() => navigate("/register")}>
              <i className="bi bi-person-plus mr-2" /> Registrar Paciente
            </Button>
          </div>
        </div>
      )}

      {appointments.length > 0 && (
        <div className="space-y-4">
          {appointments.map((appointment) => {
            const statusName = appointment.appointmentStatus?.name ?? "";
            const colorClass = statusColors[statusName] ?? "bg-gray-100 text-gray-800 border-gray-300";
            const isPaid = statusName === "Pagada";
            const isPending = statusName === "Pendiente";
            const isCancelled = statusName === "Cancelada";

            return (
              <div key={appointment.id} className={`border rounded-xl p-5 ${colorClass}`}>
                <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <h3 className="text-lg font-bold">
                        {appointment.patient?.name ?? `Paciente #${appointment.patientId}`}
                      </h3>
                      <span className={`px-2 py-1 rounded-full text-xs font-semibold border ${colorClass}`}>
                        {statusName}
                      </span>
                      {appointment.priority > 0 && (
                        <span className="px-2 py-1 rounded-full text-xs font-bold bg-red-600 text-white">
                          ­ƒÜ¿ EMERGENCIA
                        </span>
                      )}
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-sm">
                      <div><span className="font-semibold">Cita #:</span> {appointment.id}</div>
                      <div><span className="font-semibold">Especialidad:</span> {appointment.specialty?.name ?? "ÔÇö"}</div>
                      <div><span className="font-semibold">Sucursal:</span> {appointment.branch?.name ?? "ÔÇö"}</div>
                      <div><span className="font-semibold">Fecha:</span> {appointment.appointmentDate}</div>
                      <div className="col-span-2 md:col-span-4">
                        <span className="font-semibold">Motivo:</span> {appointment.reason}
                      </div>
                      {appointment.arrivalTime && (
                        <div><span className="font-semibold">Llegada:</span> {appointment.arrivalTime}</div>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col gap-2 min-w-[180px]">
                    {isPaid && !appointment.arrivalTime && (
                      <Button
                        variant="primary"
                        isDisabled={registerArrivalMutation.isPending}
                        onPress={() => registerArrivalMutation.mutate(appointment)}
                      >
                        <i className="bi bi-person-check mr-2" />
                        Registrar Llegada
                      </Button>
                    )}
                    {isPaid && (
                      <Button
                        variant="secondary"
                        onPress={() => navigate(`/appointment/reassign?appointmentId=${appointment.id}`)}
                      >
                        <i className="bi bi-person-badge mr-2" />
                        Reasignar M├®dico
                      </Button>
                    )}
                    {isPaid && appointment.arrivalTime && (
                      <div className="text-green-700 font-semibold text-sm text-center p-2 bg-green-50 rounded-lg border border-green-200">
                        Ô£à Llegada registrada
                      </div>
                    )}
                    {isPending && (
                      <>
                        <div className="text-yellow-700 text-xs text-center p-2 bg-yellow-50 rounded-lg border border-yellow-200">
                          La cita del paciente tiene estado &apos;Pendiente de pago&apos;. Debe realizar el pago en caja antes de ser atendido.
                        </div>
                        <Button
                          variant="primary"
                          onPress={() => navigate(`/payment/create?appointmentId=${appointment.id}`)}
                        >
                          <i className="bi bi-cash-coin mr-2" />
                          Ir a Caja
                        </Button>
                      </>
                    )}
                    {isCancelled && (
                      <>
                        <div className="text-red-700 text-xs text-center p-2 bg-red-50 rounded-lg border border-red-200">
                          La cita fue cancelada. El paciente debe agendar una nueva cita.
                        </div>
                        <Button variant="secondary" onPress={() => navigate("/appointment/create")}>
                          <i className="bi bi-calendar-plus mr-2" />
                          Nueva Cita
                        </Button>
                      </>
                    )}
                    {appointment.priority > 0 && (
                      <Button
                        variant="danger"
                        onPress={() => navigate(`/vital-sign/create?appointmentId=${appointment.id}`)}
                      >
                        <i className="bi bi-heart-pulse mr-2" />
                        Signos Vitales (Urgente)
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { toast } from "@heroui/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useMemo } from "react";
import { useParams } from "react-router";
import {
  getRolOperationColumns,
  type OperationWithAssignment,
} from "../../components/column/RolOperationResponseColumns";
import { LoadingComponent } from "../../components/spinner/LoadingComponent";
import { getOperations } from "../../services/operationService";
import {
  createRolOperation,
  deleteRolOperation,
  getRolOperations,
} from "../../services/rolOperationService";
import type React from "react";
import type { ApiResponse } from "../../types/ApiResponse";
import type { OperationResponse } from "../../types/OperationResponse";
import type { RolOperationResponse } from "../../types/RolOperationResponse";
import type { ApiError } from "../../types/errors";

export function RolOperationPage() {
  const { id } = useParams<{ id: string }>();
  const rolId = Number(id);
  const queryClient = useQueryClient();

  const { data: operationsData, isLoading: loadingOperations } = useQuery<
    ApiResponse<OperationResponse[]>,
    ApiError
  >({
    queryKey: ["operations"],
    queryFn: () =>
      getOperations({ pageSize: 1000, filters: "", include: "", pageNumber: 1, includeTotal: false }),
  });

  const { data: rolOperationsData, isLoading: loadingRolOperations } = useQuery<
    ApiResponse<RolOperationResponse[]>,
    ApiError
  >({
    queryKey: ["rolOperations", rolId],
    queryFn: () =>
      getRolOperations({
        pageSize: 1000,
        filters: `RolId:eq:${rolId}`,
        include: "Operation",
        pageNumber: 1,
        includeTotal: false,
      }),
  });

  const mergedRows = useMemo<OperationWithAssignment[]>(() => {
    const allOps = operationsData?.data ?? [];
    const assigned = rolOperationsData?.data ?? [];

    return allOps.map((op) => {
      const match = assigned.find((ro) => ro.operationId === op.id);
      return {
        ...op,
        assigned: !!match,
        rolOperationId: match?.id,
      };
    });
  }, [operationsData, rolOperationsData]);

  const assignMutation = useMutation({
    mutationFn: (op: OperationWithAssignment) =>
      createRolOperation({ id: null, rolId, operationId: op.id, state: 1 }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["rolOperations", rolId] });
      await queryClient.invalidateQueries({ queryKey: ["operations"] });
      toast.success("Operaci├│n asignada correctamente");
    },
    onError: () => {
      toast.danger("Error al asignar la operaci├│n");
    },
  });

  const revokeMutation = useMutation({
    mutationFn: (op: OperationWithAssignment) =>
      deleteRolOperation(op.rolOperationId!),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["rolOperations", rolId] });
      await queryClient.invalidateQueries({ queryKey: ["operations"] });
      toast.success("Operaci├│n removida correctamente");
    },
    onError: () => {
      toast.danger("Error al remover la operaci├│n");
    },
  });

  const handleToggle = (op: OperationWithAssignment) => {
    if (op.assigned) {
      revokeMutation.mutate(op);
    } else {
      assignMutation.mutate(op);
    }
  };

  const columns = useMemo(
    () => getRolOperationColumns(handleToggle),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  if (loadingOperations || loadingRolOperations) {
    return <LoadingComponent />;
  }

  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold text-center mb-4">
        Gestionar Permisos del Rol
      </h1>
      <p className="text-center text-gray-500 mb-6">
        Asigna o quita operaciones para el rol seleccionado.
      </p>
      <div className="overflow-x-auto">
        <table className="min-w-full border border-gray-200 rounded-lg">
          <thead className="bg-gray-50">
            <tr>
              {columns.map((col) => (
                <th
                  key={col.id as string}
                  className="px-4 py-2 text-left text-sm font-semibold text-gray-700"
                >
                  {col.name as string}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {mergedRows.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length}
                  className="text-center py-8 text-gray-400"
                >
                  No hay operaciones disponibles
                </td>
              </tr>
            ) : (
              mergedRows.map((row) => (
                <tr key={row.id} className="border-t border-gray-100 hover:bg-gray-50">
                  {columns.map((col) => (
                    <td key={col.id as string} className="px-4 py-2 text-sm">
                      {"cell" in col && col.cell
                        ? (col.cell as (data: OperationWithAssignment) => React.ReactNode)(row)
                        : "selector" in col && col.selector
                          ? String((col.selector as (data: OperationWithAssignment) => unknown)(row) ?? "")
                          : null}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

