/**
 * Calculates the change to return to a customer after a cash payment.
 * Uses integer arithmetic to avoid floating-point drift.
 *
 * @param amountReceived - The amount the customer handed over
 * @param amount - The total amount owed
 * @returns The change amount, rounded to 2 decimal places
 */
export function calculateChange(amountReceived: number, amount: number): number {
  return Math.round((amountReceived - amount) * 100) / 100;
}

/**
 * Validates a Guatemalan CUI/DPI number using the official modulo-11 algorithm.
 *
 * Checks:
 *  1. Exactly 13 numeric digits
 *  2. Valid department and municipality codes
 *  3. Correct check digit (modulo 11)
 *
 * @param cui - The CUI/DPI string to validate
 * @returns `true` if the CUI is structurally valid
 */
export function isCuiValid(cui: string | null | undefined): boolean {
  if (!cui) return false;

  // Remove spaces
  cui = cui.replace(/\s/g, "");

  // Must be exactly 13 digits
  if (!/^\d{13}$/.test(cui)) return false;

  // Extract parts
  const numero = cui.substring(0, 8);
  const verificador = parseInt(cui.charAt(8), 10);
  const depto = parseInt(cui.substring(9, 11), 10);
  const muni = parseInt(cui.substring(11, 13), 10);

  if (isNaN(verificador) || isNaN(depto) || isNaN(muni)) return false;

  // Municipality count per department (Guatemala has 22 departments)
  const munisPorDepto = [
    17, 8, 16, 16, 13, 14, 19, 8, 24, 21, 9,
    30, 32, 21, 8, 17, 14, 5, 11, 11, 7, 17,
  ];

  if (depto === 0 || muni === 0) return false;
  if (depto > munisPorDepto.length) return false;
  if (muni > munisPorDepto[depto - 1]) return false;

  // Validate check digit (modulo 11)
  let total = 0;
  for (let i = 0; i < numero.length; i++) {
    total += parseInt(numero[i], 10) * (i + 2);
  }

  return total % 11 === verificador;
}

/**
 * Centralized date formatting utility for the HIS application.
 * All dates from the backend are in UTC. This utility converts them
 * to the configured timezone for display.
 * 
 * The timezone is read dynamically from the authenticated user's
 * preference stored in localStorage.
 * Default timezone: America/Guatemala (UTC-6)
 */

export const APP_LOCALE = "es-GT";

const DEFAULT_TIMEZONE = "America/Guatemala";

/**
 * Reads the user's preferred timezone from localStorage.
 * Checks admin auth (@auth) first, then patient auth (@patient-auth).
 * Falls back to "America/Guatemala" if nothing is found.
 */
export function getAppTimezone(): string {
  try {
    // Try admin auth store first
    const adminAuth = window.localStorage.getItem("@auth");
    if (adminAuth) {
      const parsed = JSON.parse(adminAuth);
      if (parsed.timezoneIanaId) {
        return parsed.timezoneIanaId;
      }
    }
  } catch {
    // Fallback silently
  }

  try {
    // Try patient auth store
    const patientAuth = window.localStorage.getItem("@patient-auth");
    if (patientAuth) {
      const parsed = JSON.parse(patientAuth);
      if (parsed.timezoneIanaId) {
        return parsed.timezoneIanaId;
      }
    }
  } catch {
    // Fallback silently
  }

  return DEFAULT_TIMEZONE;
}

/**
 * Parses a date string from the backend.
 * Handles both ISO strings ("2026-04-15T14:30:00Z") and 
 * pre-formatted strings ("15/04/2026 14:30:00" which are UTC).
 */
function parseBackendDate(dateStr: string | null | undefined): Date | null {
  if (!dateStr) return null;
  
  // If it's already ISO format, parse directly
  if (dateStr.includes("T") || dateStr.endsWith("Z")) {
    const d = new Date(dateStr);
    return isNaN(d.getTime()) ? null : d;
  }
  
  // Backend format: "dd/MM/yyyy HH:mm:ss" (UTC)
  // Parse manually: day/month/year hour:minute:second
  const match = dateStr.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2}):(\d{2})$/);
  if (match) {
    const [, day, month, year, hour, min, sec] = match;
    // Create as UTC since backend stores UTC
    const d = new Date(Date.UTC(
      parseInt(year), parseInt(month) - 1, parseInt(day),
      parseInt(hour), parseInt(min), parseInt(sec)
    ));
    return isNaN(d.getTime()) ? null : d;
  }
  
  // Try date-only format: "dd/MM/yyyy"
  const dateOnly = dateStr.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (dateOnly) {
    const [, day, month, year] = dateOnly;
    const d = new Date(Date.UTC(parseInt(year), parseInt(month) - 1, parseInt(day)));
    return isNaN(d.getTime()) ? null : d;
  }
  
  // Fallback: try native parsing
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? null : d;
}

/** Format as "15/04/2026" */
export function formatDate(dateStr: string | null | undefined): string {
  const d = parseBackendDate(dateStr);
  if (!d) return dateStr ?? "ÔÇö";
  return d.toLocaleDateString(APP_LOCALE, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    timeZone: getAppTimezone(),
  });
}

/** Format as "15/04/2026 08:30" */
export function formatDateTime(dateStr: string | null | undefined): string {
  const d = parseBackendDate(dateStr);
