/** Format as "martes, 15 de abril de 2026" */
export function formatDateLong(dateStr: string | null | undefined): string {
  const d = parseBackendDate(dateStr);
  if (!d) return dateStr ?? "ÔÇö";
  return d.toLocaleDateString(APP_LOCALE, {
