  });
}

/** Format as "15 abr 2026" */
export function formatDateShort(dateStr: string | null | undefined): string {
  const d = parseBackendDate(dateStr);
  if (!d) return dateStr ?? "ÔÇö";
  return d.toLocaleDateString(APP_LOCALE, {
    year: "numeric",
    month: "short",
    day: "numeric",
    timeZone: getAppTimezone(),
  });
}

/** Format as "15 de abril de 2026, 08:30 a.m." (for receipts, confirmations) */
export function formatDateTimeLong(dateStr: string | null | undefined): string {
  const d = parseBackendDate(dateStr);
  if (!d) return dateStr ?? "ÔÇö";
  return d.toLocaleString(APP_LOCALE, {
    dateStyle: "long",
    timeStyle: "short",
    timeZone: getAppTimezone(),
  });
}

/**
 * Format a Date as a local ISO-like string "yyyy-MM-ddTHH:mm:ss"
 * WITHOUT converting to UTC. This preserves the local hour/minute
 * values which is critical when the backend needs to match the same
 * hour that was displayed to the user (e.g., slot lock keys).
 *
 * Use this instead of Date.toISOString() when sending appointment
 * dates to the backend where the local time must be preserved.
 */
export function formatLocalDateTime(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const hh = String(date.getHours()).padStart(2, '0');
  const mm = String(date.getMinutes()).padStart(2, '0');
  const ss = String(date.getSeconds()).padStart(2, '0');
  return `${y}-${m}-${d}T${hh}:${mm}:${ss}`;
}

/**
 * Decodes a JWT payload without verifying the signature.
 * Returns null if the token is malformed.
 */
export function decodeJwtPayload(token: string): Record<string, unknown> | null {
  try {
    const base64Url = token.split(".")[1];
    const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
    return JSON.parse(atob(base64)) as Record<string, unknown>;
  } catch {
    return null;
  }
}

/**
 * Extracts the role name from a JWT token.
 * Checks both the custom "RoleName" claim and the standard role claim.
 */
export function getRoleFromToken(token: string): string | null {
  const payload = decodeJwtPayload(token);
  if (!payload) return null;

  return (
    (payload["RoleName"] as string | undefined) ??
    (payload["http://schemas.microsoft.com/ws/2008/06/identity/claims/role"] as string | undefined) ??
    null
  );
}

/**
 * Validates a credit/debit card number using the Luhn algorithm.
 * @param cardNumber - The card number string (digits only, no spaces or dashes)
 * @returns true if the card number passes the Luhn check, false otherwise
 */
export function luhnCheck(cardNumber: string): boolean {
  const digits = cardNumber.replace(/\D/g, '');

  if (digits.length < 13 || digits.length > 19) {
    return false;
  }

  let sum = 0;
  let isEven = false;

  for (let i = digits.length - 1; i >= 0; i--) {
    let digit = parseInt(digits[i], 10);

    if (isEven) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    isEven = !isEven;
  }

  return sum % 10 === 0;
}

/**
 * Masks a card number, replacing all but the last 4 characters with 'ÔÇó'.
 * Strings shorter than 4 characters are returned as-is.
 *
 * @example
 * maskCardNumber('4111111111111111') // 'ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó1111'
 */
export function maskCardNumber(cardNumber: string): string {
  if (cardNumber.length <= 4) {
    return cardNumber;
  }
  const visiblePart = cardNumber.slice(-4);
  const maskedPart = 'ÔÇó'.repeat(cardNumber.length - 4);
  return maskedPart + visiblePart;
}

import { z } from "zod";
import { invalid_type_error } from "../configs/constants";
import type { ErrorObject } from "../hooks/useForm";
import { handleOneLevelZodError } from "../utils/converted";

export const appointmentSchema = z.object({
  id: z.number().nullable().optional(),
  patientId: z.union([
    z.string({ error: invalid_type_error }).min(1, "El paciente es obligatorio"),
    z.number().min(1, "El paciente es obligatorio"),
  ]),
  doctorId: z.union([
    z.string({ error: invalid_type_error }).min(1, "El m├®dico es obligatorio"),
    z.number().min(1, "El m├®dico es obligatorio"),
  ]),
  specialtyId: z.union([
    z.string({ error: invalid_type_error }).min(1, "La especialidad es obligatoria"),
    z.number().min(1, "La especialidad es obligatoria"),
  ]),
  branchId: z.union([
    z.string({ error: invalid_type_error }).min(1, "La sucursal es obligatoria"),
    z.number().min(1, "La sucursal es obligatoria"),
  ]),
  appointmentStatusId: z.union([
    z.string({ error: invalid_type_error }).min(1, "El estado es obligatorio"),
    z.number().min(1, "El estado es obligatorio"),
  ]),
  appointmentDate: z.string().min(1, "La fecha de la cita es obligatoria"),
  reason: z
    .string()
    .min(10, "El motivo debe tener al menos 10 caracteres")
    .max(2000, "El motivo no debe exceder 2000 caracteres"),
  notes: z.string().max(2000).optional().or(z.literal("")),
  state: z.union([
    z.string({ error: invalid_type_error }).min(0),
    z.number().min(0).max(1),
  ]),
});

export const validateAppointment = (data: unknown): ErrorObject => {
  const result = appointmentSchema.safeParse(data);
  if (!result.success) return handleOneLevelZodError(result.error);
  return {};
};

import { z } from "zod";
import { invalid_type_error } from "../configs/constants";
import type { ErrorObject } from "../hooks/useForm";
import { handleOneLevelZodError } from "../utils/converted";

/**
 * Base schema shared by all movement types.
 * Type-specific refinements are applied in the validate function.
 */
export const inventoryMovementSchema = z.object({
  movementType: z.union([
    z.string({ error: invalid_type_error }).min(1, "Debe seleccionar el tipo de movimiento."),
    z.number().min(0, "Debe seleccionar el tipo de movimiento.").max(5, "Tipo de operaci├│n inv├ílido"),
  ]),
  medicineId: z.union([
    z.string({ error: invalid_type_error }).min(1, "Debe seleccionar un medicamento."),
    z.number().min(1, "Debe seleccionar un medicamento."),
  ]),
  branchId: z.union([
    z.string({ error: invalid_type_error }).min(1, "Debe seleccionar una sucursal."),
    z.number().min(1, "Debe seleccionar una sucursal."),
  ]),
  quantity: z.union([
    z
      .string({ error: invalid_type_error })
      .min(1, "La cantidad es obligatoria")
      .refine((v) => Number.isInteger(Number(v)) && Number(v) > 0, "La cantidad debe ser un n├║mero entero positivo."),
    z.number().int("La cantidad debe ser un n├║mero entero positivo.").min(1, "La cantidad debe ser un n├║mero entero positivo."),
  ]),
});

export const validateInventoryMovement = (data: unknown): ErrorObject => {
  const result = inventoryMovementSchema.safeParse(data);
  const errors: ErrorObject = result.success ? {} : handleOneLevelZodError(result.error);

  const record = data as Record<string, unknown>;
  const movementType = Number(record.movementType ?? -1);

  // Compra (0): unitCost is required and must be > 0
  if (movementType === 0) {
    const cost = Number(record.unitCost);
    if (!record.unitCost && record.unitCost !== 0) {
      errors.unitCost = "El costo unitario es obligatorio para compras";
    } else if (isNaN(cost) || cost <= 0) {
      errors.unitCost = "El costo unitario debe ser mayor a 0";
    } else {
      // Validate max 2 decimal places
      const parts = String(record.unitCost).split(".");
      if (parts[1] && parts[1].length > 2) {
        errors.unitCost = "El costo unitario debe tener m├íximo 2 decimales";
      }
    }
  }

  // Ajuste+ (4) and Ajuste- (5): Notes is mandatory with min 10 chars
  if (movementType === 4 || movementType === 5) {
    const notes = String(record.notes ?? "").trim();
    if (notes.length < 10) {
      errors.notes = "El motivo debe contener entre 10 y 1000 caracteres.";
    }
  }

  return errors;
};

